-- 1. Створення таблиці plants
DROP TABLE IF EXISTS plants CASCADE;

CREATE TABLE plants (
    id SERIAL PRIMARY KEY,
    name varchar(100) NOT NULL,
    family varchar(50) DEFAULT NULL,
    type_of_life varchar(50) CHECK (type_of_life IN ('Квітуча', 'Декоративна', 'Сезонна', 'Багаторічна', 'Однорічна')),
    height text,
    flower_color varchar(100) DEFAULT NULL,
    flowering_period varchar(50) DEFAULT NULL,
    start_date char(5) DEFAULT NULL,
    end_date char(5) DEFAULT NULL,
    conditions_of_care text,
    growth_regions varchar(200) DEFAULT NULL,
    soil varchar(100) DEFAULT NULL,
    temperature varchar(50) DEFAULT NULL,
    recommended_humidity varchar(50) DEFAULT NULL,
    image text,
    description text
);

-- Індекс для швидкого пошуку за назвою
CREATE INDEX idx_plants_name ON plants(name);

-- Вставка данних після створення таблиць
INSERT INTO "plants" VALUES (1,'Квітка Астільба','Ломикаменеві','Однорічна','30–150 см','Рожевий, білий, червоний, фіолетовий','Липень–серпень','04-01','05-31','Потребує вологого ґрунту, півтіні або тіні, регулярного поливу','Помірний клімат','Рихлий, багатий на органіку, слабокислий або нейтральний','+15…+25 °C','Висока (регулярний полив)','https://wetland-plants.co.uk/wp-content/uploads/2014/12/Astilbe_chiniensis-scaled.jpg','Астільба (лат. Astilbe) – багаторічна декоративно-квітуча садова рослина. Кущі – пишні, ажурні, увінчані виразними яскравими суцвіттями. Листя – витончене декоративне, ніжно зелене, іноді з червонуватим відтінком, перисте, на довгому черешку. Це квіти напівтіні, вони прекрасно себе почувають у помірно зволожених затінених місцях. Висота рослин у середньому 50-90 см, але є і карликові низькорослі види висотою до 20 см. Астільби морозостійкі і в Україні зимують без укриття. Квіти зібрані у пишні ефектні суцвіття. Цвітіння астільби триває до сорока днів. Астільби налічують понад 40 видів та сотні сортів. На початку 20 століття почався справжній бум астільби у ландшафтному дизайні.'),(2,'Квітка Ахілея','Айстрові','Багаторічна','20–120 см','Білий, жовтий, рожевий, червоний','Червень–серпень','03-15','05-15','Стійка до посухи, любить сонячні місця, невибаглива у догляді','Помірний клімат','Супіщаний або суглинистий, добре дренований','+18…+28 °C','Низька','https://svitroslyn.ua/upload/iblock/165/165257a81d52723b059deb785e46d51b.jpg','Ахілея Millefolium Cassis добре росте на сонячних ділянках і в легкій півтіні. Вона невибаглива до ґрунтів, але краще себе почуває на пухкому, родючому, зволоженому грунті, з хорошим дренажем. Посадку рослини на постійне місце проводять навесні і восени. У контейнери їх можна садити протягом усього сезону. Для посадки готують неглибокі ямки, поміщають в них кореневища, засипають землею, не заглиблюючи бруньку, ущільнюють і добре поливають. Глибина ямки залежить від розмірів кореневища. Відстань між рослинами повинна бути не менше 25 см, а між рядами до 50 см. Ахілея Millefolium Cassis невибаглива в догляді. Для гарного росту і рясного цвітіння, її необхідно кілька разів за сезон підгодувати мінеральними добривами. У спекотну пору, при відсутності дощів, рослина потребує поливу. Також необхідно його прополювати. Після цвітіння потрібно видалити зів''ялі суцвіття. Перед зимою, надземну частину рослини обрізають трохи вище грунту.'),(3,'Квітка Агапантус','Амараллісові','Квітуча','30-150 см','Синій, білий','Червень-Серпень','03-01','06-15','Помірний полив, сонячне місце, дренований грунт','Середземноморські регіони, теплі кліматичні зони','Піщаний, слабокислий','20-25°C','Висока','https://img3.procvetok.com/crop/w500h500/24/a8/24a8a3c30e869ae6a9a6a27f2d89d9fd.jpg','У висоту міцні стебла Агапантуса виростають до 100 сантиметрів. Листя лінійне, розташовується прикоренево, сягає до 30-40 сантиметрів у довжину. Над ним височіють яскраво-сині квіти з шістьма пелюстками, що зібрані по 20-40 шт. у суцвіття діаметром до 30 сантиметрів. Цвітіння припадає на період з травня по червень. Африканська лілія чудово підходить як для поодиноких акцентів, так і для групових посадок.\nКореневище повзуче та товсте, потребує достатньо місця для росту, тому при посадці культури у горщики варто віддавати перевагу ємностям від 20 сантиметрів. Посадковий матеріал заглиблють на 5 сантиметрів. Також при вирощуванні необхідно обирати місце з гарним освітленням, адже в тіні гарне зелене листя в’яне та осипається. Культуру можна легко розмножити шляхом поділу кореневища в березні-квітні.'),(4,'Квітка Айстра','Складноцвіті','Сезонна','20-100 см','Рожевий, білий, синій, червоний','Серпень-Жовтень','04-01','06-30','Регулярний полив, сонячне або напівзатінене місце, пухкий грунт','Усі регіони помірного клімату','Родючий, слабокислий','15-20°C','Середня','https://interflora.com.ua/img/400x487/01-170.png','Айстри — це яскраві декоративні рослини з родини Айстрових, які мають зіркоподібні суцвіття різних кольорів, від білого до фіолетового. Вони цвітуть наприкінці літа або восени, прикрашаючи сади своїми ніжними й насиченими барвами, легко пристосовуються до різних умов вирощування та символізують елегантність і витонченість. Айстри підходять як для оформлення клумб, так і для зрізання, адже довго зберігають свіжість у букетах, а також часто використовуються для створення яскравих квіткових композицій.'),(5,'Квітка Алліум','Цибулеві','Декоративна','40-120 см','Фіолетовий, білий, рожевий','Травень-Червень','03-01','05-31','Мінімальний полив, сонячне місце, легкий грунт','Помірні регіони','Супіщаний, нейтральний','15-25°C','Низька','https://images.prom.ua/6057369643_w600_h600_6057369643.jpg','Квітка Алліум - декоративна цибуля, яка прикрасить ваш сад красивими, кулястими квітами. Належить до роду цибулевих і є дуже близьким родичем їстівної цибулі та часнику. Якщо потерти листя, то можна почути знайомий \"часниковий\" аромат. Незважаючи на цей запах, не варто боятися тримати його вдома, адже аромат помітний тільки якщо ви будете чіпати, терти листки. Так ви зможете відчути його аромат на руках, за інших же обставин він ледь вловимий.Листя алліума прикореневе, лілеподібне та ременеподібне. Квіти об''єднуються в суцвіття, що і створює кулясту форму. Виглядає він красиво і об''ємно. Більшість їх росте в травні-червні, але зустрічаються ті, для яких час цвітіння - осінь. У висоту досягають до 130-160 см. Цвітуть алліуми зазвичай довгий час і навіть коли цей процес закінчується, квітка залишається прекрасною і не блідне.'),(6,'Квітка Алхемілла','Розові','Багаторічна','30-60 см','Зелено-жовтий','Травень-Липень','05-01','07-15','Регулярний полив, затінене місце, добре дренований грунт','Помірні кліматичні зони','Родючий, нейтральний','15-20°C','Середня','https://www.jardineriaon.com/wp-content/uploads/2020/04/flores-de-la-planta-llamada-pie-de-leon-o-Alchemilla.jpg','Алхімелла, або манжетка (лат. Alchemilla), — це трав''яниста багаторічна рослина з родини Розових, яка вирізняється своїми округлими, ніжними листками та дрібними жовто-зеленими квітами. Її назва походить від слова «алхімія», адже рослина привертала увагу середньовічних алхіміків через здатність збирати краплини роси на поверхні листя, які вважалися «магічними».Окрім декоративної функції, манжетка має цілющі властивості. У народній медицині вона використовується як протизапальний та заспокійливий засіб, зокрема для лікування ран, застуд, жіночих хвороб і шкірних проблем.'),(7,'Квітка Альстромерія','Альстромерійні','Квітуча','50-100 см','Різнобарвна (жовта, рожева, червона)','Червень-Вересень','05-01','08-31','Помірний полив, сонячне місце, пухкий грунт','Теплі регіони, субтропіки','Супіщаний, нейтральний','18-22°C','Висока','https://yaskravaklumba.com.ua/image/cache/catalog/mnogoletniki/alstromerija/alstromerijacahors-500x500.jpg','Альстромерія Mix (Alstroemeria Mix). Альсторомерія або Альстремерія (alstroemeria), всім відома як рослина на зріз, - рідкість в наших садах. Квітки дуже нагадують метеликів. Вони також нагадують трохи квітки лілій. Вони також шестипелюсткові: складаються з трьох пелюсток і трьох чашолистків, несхожих один на одного. Їх форма кубковидна. Квітки приблизно від 5 до 6 см. Вони красиво розподілені по всій рослині. Альстромерії дуже легко вирощувати. З різних сортів можна скласти строкату композицію. А можна посадити альстромерії разом з іншими низькорослими садовими багатолітниками. Найкраще росте в півтіні / на повному сонці у вологому, але добре дренованим ґрунті.'),(8,'Квітка Амарант темний','Амарантові','Однорічна','50-150 см','Бордовий, червоний','Червень-Вересень','06-01','09-15','Регулярний полив, сонячне місце, добре дренований грунт','Теплі кліматичні зони','Родючий, слабокислий','18-25°C','Середня','https://cib.net.ua/tmp/cache/images/73/ab2/224634-469x589-r.jpg','Амарант чорний – олійна культура з великим вмістом рослинного білка та найпотужнішого з відомих антиоксидантів – сквалена. Амарант застосовується в дієтичному, спортивному та здоровому раціоні як багате джерело рослинного білка.\nЗ амаранту роблять борошно, амарантове масло або витяжку з насіння амаранту. Олія використовується для загального оздоровлення, омолоджування організму та як протипухлинний засіб. Також, насіння пророщують, проростки амаранту багаті антиоксидантами, Омега-3 кислотами, мінералами та білками. Зерна чорного амаранту смачні, легкі, хрусткі та пахнуть шоколадом під час приготування, а чорне глянсове забарвлення не руйнується при термічній обробці.'),(9,'Квітка Амарант хвостатий','Амарантові','Однорічна','60-120 см','Зелений, бордовий','Червень-Вересень','06-01','09-15','Помірний полив, сонячне або напівзатінене місце, пухкий грунт','Помірні і теплі регіони','Супіщаний, нейтральний','18-25°C','Низька','https://agrarii-razom.com.ua/sites/default/files/filefield_paths/amarant_hvostatyy_shchyrycya_hvostata1.jpg','Амарант Хвостатий — однорічна рослина з багряними суцвіттями, які створюють ілюзію казкового водоспаду або хвоста жар-птиці. Дрібні малинові квітки зібрані у довгі суцвіття до 80 см. У стародавніх греків квітка була емблемою безсмертя завдяки свіжому вигляду, який вона надовго зберігається на клумбі і в букетах. Відомий амарант також корисними властивостями. Його насіння і масло широко використовуються у народній медицині, як сечогінний, протимікробний, протизапальний засіб. У його складі багато біологічно активних речовин, білків, вітамінів, природних барвників.'),(10,'Квітка Амбрела','Зонтичні','Квітуча','40-100 см','Білий','Червень-Серпень','04-15','05-31','Помірний полив, сонячне місце, легкий грунт','Усі помірні регіони','Родючий, слабокислий','20-25°C','Середня','https://sadyba.com/image/cache/catalog/kviti/cards_new/iberis-umbrella-3-1920x1920.jpg','Іберіс Амбрелла – або іберійка парасолькова, однорічна низькоросла квітуча рослина для оформлення передніх планів бордюрів, квітників, клумб, кам’яних садів, вирощування в контейнерах або горщиках на терасі. Кущик висотою 30 см, із насичено-зеленими вузькими листочками. Дрібні ароматні квіти зібрані в пишні зонтикоподібні суцвіття білого, рожевого або фіолетового забарвлення, рясно цвітуть протягом літа. Відрізняється невибагливістю, підходить садівникам-початківцям.'),(11,'Квітка Аммі','Зонтичні','Багаторічна','60-120 см','Білий','Липень-Серпень','04-15','06-15','Мінімальний полив, сонячне місце, добре дренований грунт','Середземноморські регіони','Піщаний, нейтральний','18-25°C','Низька','https://nasivanky.com/wp-content/uploads/2024/02/ami-visnaga_green.png','Амі, або аммі (лат. Ammi), — це рід трав’янистих однорічних або багаторічних рослин з родини Зонтичних (Apiaceae), які відомі своїми ніжними, мереживними суцвіттями, схожими на дрібні парасольки. Найпоширеніші види — аммі зубна (Ammi visnaga) та аммі велика (Ammi majus), які часто вирощуються як декоративні рослини. Окрім декоративної функції, аммі має лікарські властивості. Її використовують у традиційній медицині для лікування спазмів, астми та серцево-судинних захворювань. Проте варто бути обережним, адже деякі види рослини можуть викликати подразнення шкіри через контакт із соком.'),(12,'Квітка Ананас','Бромелієві','Декоративна','50-100 см','Червоний, рожевий','Цвіте нерегулярно','01-01','12-31','Помірний полив, тепле місце, дренований грунт','Тропічні і субтропічні регіони','Родючий, слабокислий','22-28°C','Висока','https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Colananas.jpg/1200px-Colananas.jpg','Трав''яниста рослина заввишки до 1,5 м. Стебло коротке, кремезне, майже непомітне під розеткою довгого листя. Листки, зібрані в прикореневу розетку, жорсткі, сизо-зелені, з колючим краєм, 50-100 см завдовжки. Квітки численні (до 200), піднесені на високому квітконосі, лілувато-рожеві, з''являються на другий рік розвитку рослини. Квіти розкриваються поступово, починаючи від низу квітконоса і далі по спіралі до верхівки, на якій розташована розетка листя меншого розміру. Запліднені квіти перетворюються в м''ясисті соковиті плоди, які формують велике шишкоподібне супліддя. М''якуш плодів блідо-жовтий, соковитий, з приємним запахом та освіжаючим смаком. Вага суплідь може сягати 5 кг.'),(13,'Квітка Анігозантус','Гемодорові','Квітуча','50-150 см','Жовтий, червоний, зелений','Весна-Осінь','03-01','05-15','Регулярний полив, сонячне місце, добре дренований грунт','Теплі регіони, субтропіки','Піщаний, нейтральний','18-28°C','Середня','https://ukraflora.ua/image/cache/catalog/image/cache/catalog/content/cvetuchie/anigozantus-1100x1100.webp','Анігозантус, або кенгурува лапка (лат. Anigozanthos), — це багаторічна трав''яниста рослина, що походить з Австралії і належить до родини Гемодорових (Haemodoraceae). Свою назву вона отримала завдяки незвичайним квітам, які нагадують лапки кенгуру. Ця рослина стала популярною завдяки своєму екзотичному вигляду та яскравим кольорам. Ця рослина ідеально підходить для вирощування в садах із сухим кліматом, а також у контейнерах чи вазонах. Вона невибаглива, добре переносить спеку і посуху, але вимагає добре дренованого ґрунту. Анігозантус любить сонячні місця та помірний полив.'),(14,'Квітка Араукарія','Араукарієві','Декоративна','100-200 см (у горщику)','Зелений','Немає (хвойне дерево)','01-01','12-31','Помірний полив, напівзатінене місце, добре дренований грунт','Теплі та помірні регіони','Супіщаний, слабокислий','18-22°C','Висока','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT-PlLmVy3so8pqWM9nNJRByhazKNU4CHiljRyjERlF8VmX6wnxq54Qlt6kSUl0xCkC4_Q&usqp=CAU','Араукарія або кімнатна ялина - вічнозелена хвойна рослина, яку можна вирощувати в квартирі. Як і багато хвойні рослини, кімнатна ялина очищає повітря.\nУ кімнатних умовах виростає до 2 м у висоту. Араукарія зростає повільно і до 8-10 років її можна утримувати в приміщенні. Прекрасно росте в зимових садах. Доросла рослина можна висадити на відкрите повітря. Араукарія є довговічною рослиною, яка може жити десятиліттями за умови належного догляду. Араукарія стане чудовим вибором для прикрашання великих приміщень, офісів або зимових садів. Вона добре виглядає як самостійний декоративний елемент у просторих кімнатах, створюючи атмосферу свіжості та затишку. Завдяки своїй формі, араукарія виглядає елегантно як у простих керамічних горщиках, так і у вишуканих кашпо.'),(15,'Квітка Анемон','Жовтецеві','Багаторічна','15-120 см','Рожевий, білий, червоний, фіолетовий','Весна або Осінь (залежить від виду)','03-01','05-31','Регулярний полив, напівзатінок або сонце, пухкий грунт','Помірні кліматичні зони','Родючий, слабокислий','15-20°C','Середня','https://flowers.ua/images/Flowers/articles/355-img-1.jpg','Анемона, або вітряниця (лат. Anemone), — це рід трав’янистих багаторічних рослин родини Жовтецевих (Ranunculaceae), який налічує понад 150 видів. Назва походить від грецького слова «анемос», що означає «вітер», через чутливість пелюсток до найменших поривів повітря. Анемони вважаються символом ніжності, чистоти та мінливості.\nЦі рослини вирізняються витонченим виглядом: прямостоячі стебла висотою 15–120 см увінчані поодинокими або зібраними в невеликі суцвіття квітами. Забарвлення пелюсток може бути білим, рожевим, червоним, фіолетовим, синім чи жовтим. Цвітіння залежить від виду: деякі анемони квітнуть ранньою весною (напр., анемона дібровна), інші — влітку чи восени (напр., анемона японська).\nАнемони ростуть як у дикій природі (на луках, у лісах і горах), так і в садах. Вони можуть бути як тендітними ефемероїдами, що швидко відмирають після цвітіння, так і довговічними рослинами з декоративним листям і тривалим періодом цвітіння.'),(16,'Квітка Антиррінум','Подорожникові','Сезонна','20-100 см','Різнобарвна (жовтий, рожевий, червоний, білий)','Травень-Жовтень','04-01','06-30','Регулярний полив, сонячне місце, пухкий грунт','Помірні регіони','Родючий, нейтральний','18-25°C','Середня','https://semena.in.ua/content/images/38/536x536l50nn0/37270386046609.jpg','Антиріннум, або левиний зів (лат. Antirrhinum), — це рід трав’янистих однорічних і багаторічних рослин з родини Подорожникових (Plantaginaceae). Свою назву рослина отримала завдяки незвичайній формі квіток, які нагадують розкритий рот лева. Антиріннум — популярна декоративна рослина, що цінується за рясне і тривале цвітіння. Антиріннум має прямостоячі або сланкі стебла висотою від 20 до 100 см залежно від сорту. Листя ланцетне або овальне, зібране в розетку біля основи. Квітки великі, двогубі, зібрані у верхівкові кисті. Забарвлення квіток дуже різноманітне: біле, жовте, рожеве, червоне, помаранчеве, пурпурове або багатобарвне.'),(17,'Квітка Антуріум','Ароїдні','Декоративна','30-90 см','Червоний, рожевий, білий, зелений','Цвіте цілий рік','01-01','12-31','Регулярний полив, тепле і вологе місце, добре дренований грунт','Тропіки','Родючий, слабокислий','22-28°C','Висока','https://begreen.com.ua/wp-content/uploads/2016/09/Anturium.jpg','Антуріум (лат. Anthurium) — це рід тропічних рослин з родини Ароїдних (Araceae), який налічує понад 900 видів. Його назва походить від грецьких слів «anthos» — квітка і «oura» — хвіст, що відображає форму його суцвіття. Антуріум відомий своїми декоративними листям і яскравими квітами, які стали символом краси, любові та гостинності. Антуріуми вирізняються своїми блискучими, часто шкірястими листками, які можуть бути серцеподібними, стрілоподібними чи ланцетними. Їхні квіти — це суцвіття-качан, оточене кольоровим покривалом, яке може бути червоним, рожевим, білим, зеленим або навіть фіолетовим. У природі рослини зустрічаються у тропічних лісах Центральної та Південної Америки, де ростуть як епіфіти на деревах або в ґрунті.'),(18,'Квітка Артишок (цинара)','Айстрові','Квітуча','60-200 см','Фіолетовий, синій','Червень-Вересень','04-15','06-30','Регулярний полив, сонячне місце, родючий грунт','Середземноморські регіони','Родючий, слабокислий','18-25°C','Середня','https://pasika.pp.ua/media/k2/items/cache/32827062d398c3bcebce44c02ac4fa3f_XL.jpg','Багаторічна трав’яниста рослина до 2 м завв. з довгим стрижневим коренем. Стебло прямостояче, слабко галузисте, сіро-зелене. Листки перисторозсічені, іноді цільні, знизу опушені, прикореневі завд. до 0,5 м, утворюють щільну розетку. Суцвіття — кулясті чи видовжені кошики, складаються з трубчастих жовтих та язичкових синіх квіток; обгортка черепичаста, її лусочки овальні або трикутні звужені до шипика, при основі м’ясисті. Плоди — сім’янки. Цвіте на другий рік у серпні. Широко культивується у Центральній та Південній Європі, Північній Африці, Північній Америці, на Півдні України.'),(19,'Квітка Асклепія','Кутрові','Декоративна','50-120 см','Оранжевий, червоний, жовтий','Червень-Серпень','05-01','08-31','Помірний полив, сонячне місце, добре дренований грунт','Теплі та помірні регіони','Супіщаний, нейтральний','20-25°C','Низька','https://cdn.botanichka.ru/wp-content/uploads/2015/01/milkweeds2.jpg','Асклепія (Asclepias), або ваточник, — це рід багаторічних трав’янистих рослин із родини Кутрових (Apocynaceae). Рослина відома своїм декоративним виглядом і невибагливістю у догляді. Асклепія має прямостоячі стебла, на яких розташовані довгасті або ланцетоподібні листки. Квітки зазвичай невеликі, зібрані в щільні зонтикоподібні суцвіття, і мають яскраві кольори — від помаранчевого та рожевого до червоного або білого. Вони не лише прикрашають сад, але й приваблюють метеликів, особливо монархів, оскільки служать для них джерелом нектару. Ця рослина також має унікальні біологічні особливості. Її молочний сік містить токсичні сполуки (карденоліди), що робить її захищеною від більшості травоїдних тварин. Водночас цей сік використовується в медицині та навіть у промисловості — раніше його застосовували для виробництва каучуку та текстильних волокон.'),(20,'Квітка Аспарагус','Аспарагусові','Декоративна','30-100 см','Зелений','Не цвіте в декоративних формах','01-01','12-31','Регулярний полив, напівзатінок, пухкий грунт','Помірні та тропічні регіони','Родючий, слабокислий','18-25°C','Висока','https://rostok.com.ua/content/uploads/images/asparagus.jpg','Аспарагус (Asparagus) — це рід рослин із родини Аспарагусових (Asparagaceae), який включає понад 300 видів, серед яких найбільш відомий їстівний аспарагус, або спаржа (Asparagus officinalis). Однак багато видів аспарагуса вирощують як декоративні кімнатні рослини через їхній витончений вигляд. В аспарагуса тонкі, витончені стебла й ажурне листя (насправді це модифіковані гілочки — кладодії). Ця рослина невибаглива, швидко росте та може використовуватися для декорування інтер’єрів або створення квіткових композицій. Деякі види аспарагуса утворюють дрібні білі або рожеві квіти, а згодом — декоративні червоні або чорні ягоди, які, однак, є отруйними.\nАспарагус любить яскраве, розсіяне світло, але може пристосовуватися до півтіні. Він потребує регулярного поливу, але не переносить застою води. Завдяки своїй декоративності та витривалості аспарагус став одним із найпопулярніших виборів для кімнатного озеленення.'),(21,'Квітка Аспідистра','Спаржеві','Квітуча','30-70 см','Зелений','Цвіте рідко, незначне цвітіння','01-01','12-31','Мінімальний полив, напівзатінене місце, добре дренований грунт','Помірні регіони','Супіщаний, нейтральний','15-20°C','Низька','https://cdn.asterias.od.ua/images/80/80-1-61-700x700.jpg','Аспідистра (Aspidistra), або \"залізна рослина\", — це рід багаторічних трав''янистих рослин із родини Холодкових (Asparagaceae), відомий своєю стійкістю та невибагливістю. Найпоширеніший вид — аспідистра висока (Aspidistra elatior), яка стала популярною кімнатною рослиною завдяки здатності рости майже в будь-яких умовах. Її довгі, шкірясті, темно-зелені листки ростуть прямо з підземного кореневища, створюючи пишний, декоративний кущ.\nАспідистра може витримувати тінь, перепади температури, рідкісний полив і навіть недбале ставлення. Рослина зазвичай цвіте дуже рідко й лише в природних умовах або при ідеальному догляді — її квіти дрібні, непоказні, буро-фіолетового кольору, часто заховані біля основи рослини.\n\nЗавдяки своїй витривалості аспідистра чудово підходить для офісів, громадських просторів або приміщень із мінімальною кількістю світла, а також є символом витривалості та довголіття.'),(22,'Квітка Астранція','Зонтичні','Багаторічна','30-70 см','Рожевий, білий, фіолетовий','Червень-Серпень','03-15','05-31','Помірний полив, сонячне або напівзатінене місце, пухкий грунт','Помірні регіони','Родючий, слабокислий','15-22°C','Середня','https://lotosk.com.ua/image/cache/000001698_3_-1000x1000.jpg','Астранція (Astrantia) — це багаторічна трав''яниста рослина з родини Зонтичних (Apiaceae), яку часто називають \"зіркою саду\" завдяки її незвичайним квіткам. Рослина має пишні кущі з довгими стеблами, на кінцях яких розташовані квітки, що нагадують мініатюрні зірки або парасольки. Центральна частина квітки складається з дрібних квіточок, оточених декоративними приквітками. Їх колір варіюється від ніжно-білого та рожевого до насиченого червоного чи пурпурового.\nАстранція добре росте на сонячних або напівтіньових ділянках із вологим, дренованим ґрунтом. Вона чудово підходить для створення квітників, садових композицій і букетів, оскільки довго зберігає свіжість після зрізання. Її цінують за тривалий період цвітіння (з кінця весни до осені) і стійкість до хвороб і шкідників. Це невибаглива, але дуже декоративна рослина, яка додає саду шарму та витонченості.'),(23,'Квітка Бавовна','Мальвові','Квітуча','100-200 см','Білий, жовтий','Червень-Серпень','05-01','09-30','Регулярний полив, сонячне місце, родючий грунт','Тропіки і субтропіки','Родючий, слабокислий','20-30°C','Висока','https://dfb.com.ua/wp-content/uploads/2021/10/img_3500.jpg','Бавовна (Gossypium) — це рід рослин із родини Мальвових (Malvaceae), відомий своїми цінними волокнами, які використовують для виготовлення текстилю. Бавовна є напівчагарником або трав’янистою рослиною, яка вирощується в теплих регіонах світу. Вона має широкі лопатеві листки та великі квіти, які можуть бути білими, жовтими, рожевими або фіолетовими. Після цвітіння на рослині формуються коробочки, які при дозріванні розкриваються, відкриваючи м''які білі чи кремові волокна — саме вони й є основою для виробництва тканин.\nБавовна не лише забезпечує сировину для текстильної промисловості, але й має значення в косметології, медицині (бавовняна вата), і навіть у харчовій промисловості (бавовняна олія). Вирощування бавовни вимагає тепла, сонця та достатньої кількості води, але сучасні сорти адаптовані до різних умов. Її ніжний вигляд робить бавовну символом чистоти й м''якості.'),(24,'Квітка Банксія','Протейні','Квітуча','100-200 см','Жовтий, оранжевий, червоний','Весна-Осінь','01-01','12-31','Помірний полив, сонячне місце, піщаний грунт','Теплі регіони, субтропіки','Піщаний, слабокислий','18-25°C','Середня','https://ukraflora.ua/image/cache/catalog/image/cache/catalog/blog/2023/032023/bpnksija123-1100x1100.webp','Банксія (Banksia) — це рід вічнозелених дерев і чагарників із родини Протейних (Proteaceae), який є ендеміком Австралії. Ця рослина відома своїми незвичайними суцвіттями, які мають вигляд великих циліндричних або конічних \"шишок\", що складаються з сотень маленьких трубчастих квіточок. Кольори квітів варіюються від жовтого й помаранчевого до червоного й навіть фіолетового. Після цвітіння залишаються дерев’янисті плоди, що нагадують «капсули», які можуть залишатися на рослині протягом багатьох років.\nБанксія — надзвичайно декоративна рослина, яка привертає увагу своїм екзотичним виглядом. Вона також є важливим джерелом нектару для птахів, комах і дрібних ссавців. Ці рослини добре пристосовані до суворих умов: вони витримують засуху, бідні ґрунти та навіть лісові пожежі. Банксія часто використовується в ландшафтному дизайні та як зрізна квітка завдяки своїй тривалій декоративності.\n\n'),(25,'Квітка Барбарис','Барбарисові','Декоративна','50-300 см','Жовтий','Травень-Червень','02-15','04-30','Регулярний полив, сонячне або напівзатінене місце, добре дренований грунт','Помірні регіони','Супіщаний, слабокислий','15-25°C','Середня','https://profisad.com.ua/wp-content/uploads/2023/04/barbaris.jpg','Барбарис (Berberis) — це рід чагарників із родини Барбарисових (Berberidaceae), який включає понад 400 видів. Барбарис відомий своїми колючими гілками, дрібними шкірястими листками та яскравими ягодами, які дозрівають наприкінці літа або восени. У період цвітіння чагарник вкривається жовтими або оранжевими квітками, що приваблюють бджіл і метеликів.\nБарбарис цінується за свою декоративність і невибагливість. Він часто використовується в садовому дизайні для створення живих огорож, бордюрів або як солітер. Ягоди барбарису, хоча й кислі на смак, використовуються в кулінарії — їх додають до страв, консервують або сушать. Крім того, барбарис має цілющі властивості: його ягоди та кора багаті на вітаміни й корисні речовини, які застосовують у народній медицині для зміцнення імунітету та поліпшення травлення.\n\nБарбарис легко адаптується до різних умов, росте як на сонці, так і в напівтіні, і добре переносить обрізку, що робить його ідеальним вибором для декоративного садівництва.'),(26,'Квітка Берграс','Злакові','Декоративна','50-150 см','Зелений','Цвіте рідко','01-01','12-31','Мінімальний полив, сонячне місце, піщаний грунт','Помірні та теплі регіони','Супіщаний, нейтральний','18-25°C','Низька','https://kvitka-distribution.com.ua/content/images/24/480x480l50nn0/35156743776134.jpg','Берграс (Beargrass), або ксерофіллум (лат. Xerophyllum tenax), — це багаторічна трав''яниста рослина, що належить до родини Мелантієвих (Melanthiaceae). Вона зустрічається в основному в Північній Америці, на територіях із помірним кліматом. Рослина має довге, вузьке, жорстке листя, що утворює густі пучки, схожі на траву. У період цвітіння берграс випускає високе стебло, увінчане великим суцвіттям із численних дрібних білих або кремових квітів, які мають легкий солодкий аромат.\nБерграс не лише декоративний, але й має практичне значення. Його волокна використовували корінні американці для плетіння кошиків і виготовлення мотузок. Рослина добре росте на бідних ґрунтах, витримує засуху та є невибагливою у догляді, що робить її популярною у ландшафтному дизайні, особливо в садах із природним або прерієвим стилем.'),(27,'Квітка Берзелія','Миртові','Декоративна','50-100 см','Зелений, білий','Листопад-Лютий','03-01','05-31','Регулярний полив, напівзатінок, пухкий грунт','Субтропіки','Родючий, слабокислий','15-20°C','Висока','https://rozy.com.ua/img/scif1_add/spr_noms/6/6894/6894_78_20240914092221_0847.jpg','Берзелія (Berzelia) — це екзотичний рід вічнозелених чагарників із родини Миртових (Myrtaceae), що походить із Південної Африки. Ця рослина є унікальним декоративним елементом завдяки своїм незвичайним суцвіттям: дрібні кулясті голівки квітів щільно зібрані у групи на тонких стеблах. Суцвіття мають білий, кремовий або світло-зелений відтінок, а після цвітіння залишаються декоративні плоди, які довго зберігають свою форму.\nБерзелія є популярною серед флористів, адже її кулясті суцвіття використовують для створення букетів, весільних композицій і декору. Рослина символізує витонченість і мінімалізм. У природі берзелія росте на добре дренованих піщаних ґрунтах і потребує багато сонця. У садівництві її вирощують як декоративну рослину, яка надає екзотичний акцент будь-якому квітнику чи композиції.'),(28,'Квітка Брасіка','Хрестоцвіті','Квітуча','30-70 см','Рожевий, білий, фіолетовий','Жовтень-Грудень','06-01','08-31','Регулярний полив, сонячне місце, добре дренований грунт','Помірні регіони','Родючий, слабокислий','10-18°C','Середня','https://family-flowers.com.ua/wp-content/uploads/2021/08/DSC_0242.jpg','Брасіка (Brassica) — це рід рослин із родини Капустяних (Brassicaceae), що включає різноманітні овочеві культури, такі як капуста, броколі, кольорова капуста, брюссельська капуста та багато інших. Крім харчового значення, брасіка має декоративні сорти, відомі як декоративна капуста. Їх вирощують через яскраво забарвлені розетки листя, які нагадують квіткові бутони. Таке листя може бути білим, рожевим, пурпуровим, зеленим або їхньою комбінацією.\nДекоративна брасіка часто використовується в озелененні восени та взимку, оскільки її яскраві кольори зберігаються навіть при низьких температурах. Вона невибаглива до догляду й добре росте як на клумбах, так і в контейнерах. У кулінарних видів брасіки листя, суцвіття й навіть насіння широко використовуються в різних стравах, збагачуючи раціон вітамінами та мінералами.'),(29,'Квітка Брунія','Брунієві','Декоративна','50-150 см','Сірий, білий','Осінь-Зима','03-01','05-31','Помірний полив, сонячне місце, добре дренований грунт','Субтропіки','Піщаний, нейтральний','15-20°C','Середня','https://rozy.com.ua/img/scif1_add/spr_noms/2/2559/2559_57_20220717094440_932.jpg','Брунія (Brunia) — це рід вічнозелених чагарників із родини Брунієвих (Bruniaceae), які природно зростають у Південній Африці. Ця рослина відома своїми незвичайними кулястими суцвіттями, які складаються з численних дрібних квітів. Після цвітіння залишаються декоративні плоди, які виглядають як сріблясто-сірі або зеленуваті кульки. Саме ці кульки роблять брунію популярною у флористиці, оскільки вони додають композиціям текстури та екзотичного вигляду.\nБрунія зазвичай має компактну форму та невеликі вузькі листочки. Вона чудово росте в добре дренованих ґрунтах і любить сонячне світло. У флористиці брунія використовується для створення букетів і декору, оскільки її плоди довго зберігають свою декоративність і не втрачають вигляду після зрізання. Її часто асоціюють із елегантністю та сучасним стилем.'),(30,'Квітка Бувардія','Маренові','Квітуча','30-90 см','Рожевий, білий, червоний','Квітень-Жовтень','03-15','06-15','Регулярний полив, тепле місце, родючий грунт','Тропіки','Родючий, слабокислий','18-25°C','Висока','https://cdn.asterias.od.ua/images/253/253-5-9-700x615.jpg','Бувардія (Bouvardia) — це рід тропічних і субтропічних чагарників із родини Маренових (Rubiaceae), який походить із Центральної та Південної Америки. Рослина відома своїми яскравими, трубчастими квітами, які зібрані у щільні суцвіття-парасольки. Квіти бувардії бувають різних кольорів: білого, рожевого, червоного, коралового або жовтого. Завдяки своїй витонченості вони символізують ентузіазм і радість, а тому часто використовуються у флористиці для створення святкових композицій та букетів.\nБувардія потребує теплого клімату, розсіяного сонячного світла та регулярного поливу. Вона може вирощуватися як кімнатна рослина, а в теплих регіонах — як декоративний чагарник. Її цвітіння триває довго, що робить її популярною для прикрашання інтер’єрів. Завдяки своєму приємному аромату, бувардія також привертає метеликів і бджіл, якщо вирощується в саду.'),(31,'Квітка Бузок','Маслинові','Квітуча','200-500 см','Фіолетовий, рожевий, білий','Квітень-Травень','03-15','05-31','Регулярний полив, сонячне місце, родючий грунт','Помірні регіони','Родючий, слабокислий','15-20°C','Середня','https://images.prom.ua/2780501644_w600_h600_2780501644.jpg','Бузок (Syringa) — це рід чагарників або невеликих дерев із родини Маслинових (Oleaceae), який широко поширений у декоративному садівництві. Рослина цінується за свої великі ароматні суцвіття, які складаються з безлічі дрібних квітів, що мають білий, фіолетовий, рожевий або блакитний відтінок. Бузок асоціюється з весною, адже цвіте у квітні-травні, наповнюючи сади ніжним солодким ароматом.\nБузок невибагливий у догляді, добре переносить помірні морози й може рости як на сонячних місцях, так і в напівтіні. Його висаджують як солітер або в групових композиціях, а також використовують для створення живоплотів. У культурі бузок має символічне значення: у різних країнах він асоціюється з юністю, чистотою та романтикою. Зрізані суцвіття часто використовують для прикрашання інтер’єрів завдяки їхньому тривалому аромату.\n\nБузок також має лікувальні властивості: його квіти, кора й листя застосовуються в народній медицині для виготовлення настоянок і мазей.'),(32,'Квітка Буплерум','Зонтичні','Сезонна','30-80 см','Зелений, жовтий','Липень-Серпень','03-15','05-31','Помірний полив, сонячне місце, пухкий грунт','Помірні регіони','Супіщаний, нейтральний','18-25°C','Середня','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTLYWQWw1yGv3VLkJ27kQAwfWTZqDpYzEdokw&s','Буплерум (Bupleurum), або воловик, — це рід трав''янистих рослин із родини Зонтичних (Apiaceae), що налічує понад 190 видів. Вони природно зростають у Європі, Азії та Північній Африці. Буплерум вирізняється своїми тонкими стеблами, вузьким ланцетоподібним або овальним листям і маленькими, схожими на зірочки, квітками, які зібрані в зонтикоподібні суцвіття. Квіти зазвичай жовті або зеленуваті, що додає їм незвичайного вигляду серед декоративних рослин.\nУ флористиці буплерум часто використовують як доповнення до букетів і композицій завдяки його ніжному вигляду й повітряній текстурі. Рослина символізує природність і витонченість. У садівництві буплерум підходить для створення квітників у стилі \"дикої природи\". Він любить сонце, добре дренований ґрунт і легко переносить посушливі періоди.\n\nОкрім декоративної ролі, буплерум використовують у народній медицині: його корені мають протизапальні й імуностимулюючі властивості, особливо в традиційній китайській медицині.'),(33,'Квітка Ванда','Орхідні','Квітуча','40-100 см','Рожевий, фіолетовий, білий','Квітень-Серпень','01-01','12-31','Висока вологість, розсіяне світло, регулярний полив','Тропіки','Епіпітний субстрат','18-25°C','Висока','https://images.floristics.info/images/stati_photo/orhideya_vanda/orhideya_vanda2_2.jpg','Ванда (Vanda) — це рід орхідей із родини Орхідних (Orchidaceae), який вважається одним із найвишуканіших і найцінніших у світі. Ванди походять із тропічних регіонів Азії, зокрема з Індії, Таїланду, Індонезії та Філіппін. Ці орхідеї відомі своїми великими, яскравими квітками, що бувають різних кольорів — від білого й рожевого до фіолетового, синього й жовтого. Малюнок на пелюстках часто має складну сітчасту структуру, що додає квітці розкішного вигляду.\nВанда — епіфітна рослина, тобто в природі вона росте на деревах, отримуючи вологу й поживні речовини з повітря. У домашніх умовах її часто вирощують без ґрунту, закріплюючи коріння на опорах або тримаючи в спеціальних скляних вазах. Ванда потребує яскравого розсіяного світла, високої вологості й регулярного поливу.\nЦі орхідеї — справжня окраса інтер’єру, їх квіти тримаються на рослині до трьох місяців. У флористиці ванда є символом розкоші й елегантності, її часто використовують у весільних композиціях і престижних букетах. Вона ідеально підходить для тих, хто шукає екзотичну та вишукану квітку для дому чи подарунка.'),(34,'Квітка Верба','Вербові','Сезонна','200-2500 см','Жовтий','Березень-Квітень','02-01','04-15','Помірний полив, вологий грунт, сонячне місце','Помірні регіони','Вологий, слабокислий','5-20°C','Середня','https://sad-gorod.com.ua/storage/products_images/medium/2018-02-13-17-19-57.jpg','Верба (Salix) — це рід листопадних дерев і чагарників із родини Вербових (Salicaceae), який нараховує понад 400 видів. Верба широко поширена в помірному кліматі, особливо поблизу водних джерел. Її тонкі, гнучкі гілки, вузьке або овальне листя і витончені форми роблять її однією з найбільш упізнаваних рослин. Навесні верба цвіте пухнастими сережками, які часто називають \"котиками\". Цвітіння зазвичай символізує прихід весни, і верба має важливе значення в народних традиціях, зокрема у Великодніх обрядах.\nВерба невибаглива, швидко росте й легко переносить обрізку, тому її часто використовують у ландшафтному дизайні. Вона може слугувати як декоративною рослиною, так і частиною екосистеми, оскільки стабілізує береги водойм і створює середовище для птахів і комах. У народній медицині верба цінується за її кору, багату на саліцин, який є природним протизапальним засобом.'),(35,'Квітка Верес','Вересові','Багаторічна','20-50 см','Рожевий, білий, фіолетовий','Серпень-Жовтень','03-01','05-15','Кислий грунт, помірний полив, сонячне місце','Помірні регіони','Кислий, супіщаний','10-20°C','Середня','https://pustunchik.ua/uploads/school/98c77b83a1149d3cf4aa1209997b2952.jpg','Верес (Calluna vulgaris) — це низькорослий вічнозелений чагарник із родини Вересових (Ericaceae), який широко поширений у Європі, Азії та Північній Америці. Він утворює щільні килими й є одним із головних видів рослин, які заселяють відкриті, піщані або болотисті території. Верес має дрібне голкоподібне листя і крихітні дзвіночкоподібні квіти, які з’являються наприкінці літа й тримаються до осені. Квіти можуть бути білими, рожевими, фіолетовими або пурпуровими, і вони додають природному ландшафту яскравих акцентів.\nВерес часто використовують у декоративному садівництві для створення альпійських гірок, бордюрів і композицій із багаторічників. Він добре росте на кислих, піщаних ґрунтах і є символом витривалості й невибагливості. У культурі верес асоціюється з романтикою, захистом і щастям, а в Шотландії його вважають національним символом.\nОкрім декоративної ролі, верес має й практичне значення: його квіти використовують для виготовлення меду, а в народній медицині настої з вересу застосовуються для лікування сечостатевих захворювань і заспокоєння нервової системи.'),(36,'Квітка Вероніка','Подорожникові','Квітуча','30-70 см','Синій, білий, рожевий','Червень-Серпень','03-15','06-15','Помірний полив, сонячне або напівзатінене місце, дренований грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://shemrit.com.ua/image/catalog/shemrit/product-images/%D0%9C%D0%BD%D0%BE%D0%B3%D0%BE%D0%BB%D0%B5%D1%82%D0%BD%D0%B8%D0%B5_%D1%86%D0%B2%D0%B5%D1%82%D1%8B/veronica-spicata-blue.jpg','Вероніка (Veronica) — це рід трав''янистих рослин і напівчагарників із родини Подорожникових (Plantaginaceae), що включає понад 500 видів. Вероніка зустрічається в багатьох частинах світу, від помірних регіонів Європи й Азії до Нової Зеландії. Її дрібні квітки зазвичай синього, фіолетового, білого або рожевого кольору, зібрані в колосоподібні або китицеподібні суцвіття. Рослина має витончений вигляд і тривалий період цвітіння, що робить її популярною як у природному середовищі, так і в садівництві.\nВероніка невибаглива, добре переносить різні типи ґрунтів і кліматичні умови. Вона ідеально підходить для клумб, рокаріїв, альпійських гірок і бордюрів, а також часто використовується в садках природного стилю. У народній медицині вероніку застосовують для лікування запальних процесів і травних розладів, оскільки її листя й квіти мають протизапальні й антисептичні властивості.'),(37,'Квітка Волошка','Айстрові','Сезонна','30-80 см','Синій, білий, рожевий','Травень-Серпень','03-15','05-31','Помірний полив, сонячне місце, пухкий грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://poradnica.com.ua/wp-content/uploads/2018/05/vas-e1526021298524.jpg','Волошка (Centaurea) — це рід трав''янистих рослин із родини Айстрових (Asteraceae), який включає понад 600 видів. Найвідоміший представник роду — волошка синя (Centaurea cyanus), що є символом полів і луків завдяки своїм яскраво-блакитним квітам. Квітки волошки можуть бути не лише синіми, але й рожевими, білими, фіолетовими або жовтими залежно від виду. Вони мають характерну форму із загостреними пелюстками, що створює ефект витонченої зірки.\nВолошка невибаглива, легко росте на відкритих сонячних ділянках і добре переносить посуху. Її висаджують як декоративну рослину для клумб, квітників і природних садів. У флористиці вона використовується як зрізна квітка завдяки своїй стійкості й тривалому збереженню декоративності.\nУ народній культурі волошка символізує чистоту, ніжність і романтику. Вона також має лікувальні властивості: настої з квіток використовуються для поліпшення зору, зняття запалень і лікування шкірних захворювань. Волошковий мед вважається одним із найароматніших і найкорисніших сортів.'),(38,'Квітка Вібурнум','Адоксові','Декоративна','200-400 см','Білий','Травень-Червень','04-01','05-31','Помірний полив, сонячне або напівзатінене місце, родючий грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://donpion.ua/static/media/uploads/product/One_flower/viburnum/.thumbnails/eb2cad23c994ac634d5d5f1ee22de74b.jpg/eb2cad23c994ac634d5d5f1ee22de74b-472x472.jpg','Вібурнум (Viburnum) — це рід рослин, який включає безліч видів, що вирізняються красою та універсальністю у садівництві. Залежно від виду, вібурнум може бути у вигляді куща або невеликого дерева. Ця рослина відома своїм пишним цвітінням навесні та привабливими ягодами восени. Листя, зазвичай темно-зелене, восени набуває яскравих кольорів, додаючи саду декоративності. Вібурнум легко адаптується до різних умов і часто використовується в живоплотах або як акцентна рослина.'),(39,'Квітка Вібурнум (ягоди)','Адоксові','Декоративна','200-400 см','Червоний (ягоди)','Серпень-Жовтень (плоди)','05-01','09-15','Помірний полив, родючий грунт, сонячне місце','Помірні регіони','Родючий, слабокислий','10-20°C','Середня','https://megacvet24.ru/image/catalog/viburnum-chernyy.jpeg','Вібурнум з ягодами — це окремий аспект декоративності цього роду. Після цвітіння з’являються плоди, які можуть бути червоними, чорними, синіми чи навіть білими, залежно від виду. Найбільш популярний вид із червоними ягодами — це Viburnum opulus (калина звичайна). Її яскраві грона червоних ягід не лише прикрашають ландшафт, але й мають лікувальні властивості, широко використовуються в народній медицині. Ягоди можуть залишатися на рослині навіть після того, як опаде листя, створюючи яскравий акцент у зимовому саду.'),(40,'Квітка Геліконія','Геліконієві','Квітуча','100-300 см','Червоний, жовтий, помаранчевий','Квітень-Серпень','01-01','12-31','Висока вологість, регулярний полив, розсіяне світло','Тропіки і субтропіки','Родючий, добре дренований','20-30°C','Висока','https://orchidsart.com/wp-content/uploads/2018/11/%D0%A5%D0%B5%D0%BB%D0%B8%D0%BA%D0%BE%D0%BD%D0%B8%D1%8F.jpg','Геліконія (Heliconia) — це тропічна рослина, яка зачаровує своєю екзотичною красою. Вона належить до однойменного роду Heliconia і зустрічається в природі переважно в Центральній і Південній Америці, а також на островах Карибського басейну. Її найбільш впізнаваною рисою є яскраві суцвіття, які нагадують пташині дзьоби або бананові квіти. Ці суцвіття складаються з кольорових приквітків червоного, жовтого, помаранчевого або рожевого кольорів, які часто приховують дрібні квітки. Геліконія є невибагливою до умов, якщо отримує достатньо тепла, вологи та світла, що робить її популярною в тропічних садах і для вирощування у великих горщиках. Її часто називають \"райською квіткою\" завдяки екзотичному вигляду. У природному середовищі рослина є важливим джерелом нектару для птахів, зокрема для колібрі.\nГеліконії мають довгі, широкі листки, схожі на бананові, що додає тропічного шарму. Вони також використовуються в ландшафтному дизайні для створення яскравих акцентів або живих бар''єрів. Завдяки своїй здатності очищати повітря, ця рослина може бути чудовим доповненням до інтер’єру.'),(41,'Квітка Геніста','Бобові','Сезонна','50-100 см','Жовтий','Травень-Червень','03-01','05-31','Сонячне місце, помірний полив, піщаний грунт','Середземноморські регіони','Піщаний, нейтральний','15-25°C','Низька','https://novyjsad.com.ua/wp-content/uploads/2021/01/Drok-krasyln-y.jpg','Геніста (Genista) — це рід квіткових рослин із родини бобових (Fabaceae), відомий своїми запашними, золотисто-жовтими квітами. Ці кущі або напівкущі широко поширені в Європі, особливо в Середземноморському регіоні, де вони ростуть у сухих, сонячних умовах. Геніста ідеально підходить для декоративного використання в садах завдяки своїй витривалості та яскравому цвітінню, яке триває навесні й на початку літа. Вона може рости на кам''янистих ґрунтах, схилах і навіть у несприятливих умовах, тому її часто висаджують для стабілізації ґрунту.\nГеніста має компактний розмір, що робить її придатною для вирощування як у клумбах, так і в горщиках. Її листя зазвичай вузьке, темно-зелене, добре контрастує з жовтими квітами. Ця рослина приваблює запилювачів, таких як бджоли, які грають важливу роль у її розмноженні. Іноді геністу використовують як сировину для отримання натуральних барвників, а також у традиційному озелененні для створення мальовничих природних куточків.\n\nДодатково, завдяки своїй здатності фіксувати азот у ґрунті, геніста сприяє покращенню його родючості. Вона є чудовим вибором для садівників, які прагнуть додати до своїх ділянок яскраві кольори та витривалі рослини.'),(42,'Квітка Гербера','Айстрові','Декоративна','30-60 см','Рожевий, червоний, білий, жовтий','Квітень-Жовтень','04-01','06-30','Регулярний полив, розсіяне світло, пухкий грунт','Помірні і теплі регіони','Родючий, слабокислий','18-25°C','Середня','https://upload.wikimedia.org/wikipedia/commons/0/09/Gerbera01.jpg','Гербера (Gerbera) — це яскрава і популярна декоративна рослина, яка належить до родини айстрових (Asteraceae). Її рід включає понад 30 видів, що походять із тропічних і субтропічних регіонів Африки, Азії та Південної Америки. Гербери відомі своїми великими квітами у вигляді кошиків, які можуть бути білими, жовтими, рожевими, помаранчевими, червоними чи навіть пурпуровими. Центральна частина квітки часто контрастує з пелюстками, додаючи їй декоративності. Завдяки своїй стійкості гербери є улюбленими квітами для зрізу, використовуються в букетах і композиціях.\nРослина добре росте як у відкритому ґрунті, так і в горщиках, якщо їй забезпечити достатньо світла та помірний полив. Гербери цінуються за їхню тривалість цвітіння і здатність очищати повітря в приміщеннях. У садах їх висаджують для створення яскравих акцентів або комбінування з іншими багаторічниками. Вони символізують радість, щирість і дружбу, що робить їх чудовим подарунком для особливих моментів.'),(43,'Квітка Гладіолус','Ірисові','Квітуча','50-150 см','Рожевий, червоний, білий, жовтий, фіолетовий','Липень-Вересень','06-01','08-31','Сонячне місце, регулярний полив, родючий грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://sadubykovunu.com.ua/image/cache/catalog/image/cache/catalog/category/2-46-600x600.webp','Гладіолус (Gladiolus) — це витончена багаторічна рослина з родини ірисових (Iridaceae), яка походить із Африки, Середземномор’я та Азії. Його величні квіткові стрілки можуть досягати висоти до 1,5 метра, прикрашені численними квітками, що розпускаються зверху вниз. Квіти гладіолуса бувають різноманітних кольорів, включаючи білий, рожевий, червоний, помаранчевий, фіолетовий і жовтий, іноді з контрастними відтінками або візерунками.\nЦю рослину вирощують із бульбоцибулин, які потрібно висаджувати навесні. Гладіолуси люблять сонячні ділянки, добре дренований ґрунт і регулярний полив. Їх часто використовують для створення вертикальних акцентів у квітниках, а також для зрізу — вони чудово стоять у вазах і підходять для урочистих композицій. У квітковій символіці гладіолус асоціюється із силою, честю та любов’ю, що робить його популярним вибором для святкових подій.'),(44,'Квітка Глоріоза','Лілійні','Квітуча','100-200 см','Червоний, жовтий, помаранчевий','Червень-Вересень','07-01','09-30','Вологий грунт, регулярний полив, напівзатінок','Тропіки','Родючий, добре дренований','20-30°C','Висока','https://agrarii-razom.com.ua/sites/default/files/byr/glorioza.jpg','Глоріоза (Gloriosa) — це надзвичайно декоративна і екзотична рослина з родини Colchicaceae, яку часто називають \"вогняною лілією\" або \"ліаною слави\". Її батьківщина — тропічні регіони Африки та Азії. Глоріоза — це трав’яниста ліана, яка використовує свої гнучкі стебла для того, щоб чіплятися за опору і досягати висоти до 2-3 метрів. Її унікальні, яскраво забарвлені квітки мають хвилясті пелюстки, які поступово змінюють колір від жовтого до червоного, створюючи ефект \"полум’я\".\nГлоріозу вирощують у горщиках або теплицях, адже вона потребує теплого клімату та добре дренованого ґрунту. Рослина цвіте з середини літа до початку осені, додаючи саду нотку тропічної елегантності. Попри свою красу, глоріоза є отруйною, тому слід уникати контакту її соку з шкірою та оберігати дітей і тварин. У декоративному садівництві її використовують для вертикального озеленення або як частину екзотичних композицій. Вона символізує гідність, славу і перемогу, що пояснює її популярність у флористиці.'),(45,'Квітка Гортензія','Гортензієві','Декоративна','100-300 см','Білий, рожевий, блакитний, фіолетовий','Червень-Вересень','05-01','09-30','Регулярний полив, напівзатінок, кислий грунт','Помірні регіони','Кислий, родючий','15-25°C','Висока','https://yaskrava.com.ua/image/cache/catalog/dekorativnyekusty/gortenzii/fabolo-blue-500x500.jpg','Гортензія (Hydrangea) — це розкішна квіткова рослина з родини Гортензієвих (Hydrangeaceae), яка славиться своїми пишними суцвіттями у формі кулі або мітлиці. Вона походить із Східної Азії та Америки, де росте як кущ, невелике дерево або навіть ліана. Гортензії цінуються за різноманітність забарвлення: білі, рожеві, сині, фіолетові та навіть зеленуваті відтінки. Особливістю цієї рослини є здатність змінювати колір квітів залежно від кислотності ґрунту: в кислому середовищі квіти стають синіми, у лужному — рожевими.\nЦвітіння гортензії триває з кінця весни до початку осені, створюючи в саду атмосферу романтики та ніжності. Вона потребує вологого, добре дренованого ґрунту і помірного освітлення, що робить її ідеальною для півтіньових місць. Гортензії часто використовують у ландшафтному дизайні для створення живих огорож, акцентних зон або у великих декоративних горщиках. Символіка цієї рослини асоціюється з вдячністю, щирістю та глибокими почуттями, що робить її популярною в квіткових композиціях і подарунках.'),(46,'Квітка Гревілея','Протейні','Квітуча','150-300 см','Червоний, жовтий, рожевий','Березень-Жовтень','04-01','07-31','Сонячне місце, помірний полив, добре дренований грунт','Субтропіки','Піщаний, нейтральний','18-25°C','Середня','https://kvity.org.ua/wp-content/uploads/ewx_17500.jpg','Гревілея (Grevillea) — це декоративна рослина з родини Протейних (Proteaceae), яка походить із Австралії, де вона є символом місцевої флори. Цей рід включає понад 360 видів, які варіюються від невеликих кущів до високих дерев. Гревілея славиться своїми екзотичними, павукоподібними або китицеподібними суцвіттями, які можуть бути червоними, помаранчевими, рожевими, жовтими чи білими. Вони багаті на нектар і привертають птахів та комах-запилювачів, що робить її важливим компонентом екосистеми.\nГревілея легко адаптується до різних умов, але віддає перевагу добре дренованим ґрунтам і сонячним місцям. Вона ідеально підходить для посушливих регіонів, оскільки має високу посухостійкість. У ландшафтному дизайні її використовують для створення барвистих живих огорож, акцентних композицій або для вирощування в контейнерах. Крім декоративної цінності, деякі види гревілеї мають деревину, що використовується в ремісництві. Вона символізує витривалість і гармонію з природою.'),(47,'Квітка Гіацинт','Спаржеві','Квітуча','20-50 см','Рожевий, білий, синій, фіолетовий','Березень-Квітень','03-01','04-30','Сонячне місце, регулярний полив, пухкий грунт','Помірні регіони','Родючий, нейтральний','10-20°C','Середня','https://floralife.com.ua/image/cache/catalog/encyclopedia/hyacinthus-enc/hyacinthus-01-9-1200x900.jpg','Гіацинт (Hyacinthus) — це квітуча рослина з родини спаржевих (Asparagaceae), яка захоплює своїм ароматом і яскравим цвітінням. Його батьківщина — Середземномор’я і Західна Азія, але нині він культивується по всьому світу. Гіацинти вирощують із цибулин, які навесні розкривають суцвіття-кісти з безліччю дрібних квіток. Їхнє забарвлення може варіюватися від білого, рожевого, червоного і синього до фіолетового та жовтого.\nГіацинт символізує радість, відродження і красу, тому його часто використовують у весняних квіткових композиціях. Рослина віддає перевагу добре дренованому ґрунту та сонячним місцям, хоча може цвісти й у півтіні. Гіацинти чудово виглядають у клумбах, альпінаріях, а також як горщикові рослини. Їхній сильний аромат здатен наповнити кімнату або сад атмосферою свіжості. У квітковій символіці вони також можуть означати відданість і щирість почуттів, залежно від кольору.'),(48,'Квітка Гіпеаструм','Амараллісові','Квітуча','30-70 см','Червоний, білий, рожевий','Січень-Квітень','12-01','03-31','Регулярний полив, розсіяне світло, пухкий грунт','Тропіки і субтропіки','Родючий, слабокислий','18-25°C','Середня','https://svitroslyn.ua/upload/iblock/a1e/a1e8bc7c7146c4d4a952ee43083d31e8.jpg','Гіпеаструм (Hippeastrum) — це яскрава цибулинна рослина з родини амарилісових (Amaryllidaceae), яка зачаровує своїми великими, лійкоподібними квітами. Вона походить із тропічних і субтропічних регіонів Америки, але завдяки селекції стала популярною у всьому світі як декоративна кімнатна й садова культура. Гіпеаструм має довгі прямостоячі квітконоси, які можуть досягати висоти 60-70 см і нести до шести квітів різних відтінків: білого, червоного, рожевого, помаранчевого або двоколірного. Її листя вузьке й довге, додає рослині елегантності навіть поза періодом цвітіння.\nЦя рослина цвіте зазвичай узимку або ранньою весною, що робить її популярною для домашнього вирощування. Гіпеаструм любить яскраве розсіяне світло, помірний полив і добре дренований ґрунт. Його часто вирощують для декоративного оздоблення приміщень або садів, а також використовують у зрізі для створення ефектних квіткових композицій. У символіці квітів гіпеаструм асоціюється з гордістю, захопленням і красою.'),(49,'Квітка Гіпсофіла','Гвоздичні','Декоративна','50-120 см','Білий, рожевий','Червень-Серпень','06-01','09-30','Сонячне місце, мінімальний полив, добре дренований грунт','Помірні регіони','Піщаний, нейтральний','15-25°C','Низька','https://camellia-market.com.ua/image/cache/catalog/gipsofila/gipsofilabelaja-auto_width_1333.jpg','Гіпсофіла (Gypsophila) — ніжна і витончена рослина з родини гвоздикових (Caryophyllaceae), яку часто називають «диханням немовляти» завдяки її легкому, повітряному вигляду. Її батьківщиною є Європа, Азія та Північна Африка. Гіпсофіла — це трав’янистий багаторічник або однорічник із тонкими розгалуженими стеблами, прикрашеними дрібними білими або рожевими квітками. Рослина утворює пишні, майже прозорі хмарки, які чудово доповнюють будь-які квіткові композиції.\nГіпсофіла любить сонячні ділянки з добре дренованим ґрунтом і вимагає мінімального догляду. Вона часто використовується як декоративний елемент у букетах, особливо весільних, або як ґрунтопокривна рослина для клумб і альпінаріїв. Гіпсофіла символізує чистоту, ніжність і невинність, що робить її улюбленою квіткою для романтичних подій і композицій.'),(50,'Квітка Даукус','Зонтичні','Сезонна','30-100 см','Білий, кремовий','Червень-Серпень','07-01','09-30','Сонячне місце, помірний полив, добре дренований грунт','Помірні регіони','Піщаний, нейтральний','15-25°C','Середня','https://nasivanky.com/wp-content/uploads/2024/01/daykys-carota_dara-2.jpg','Даукус (Daucus carota) — декоративна форма дикої моркви, відома своїми ажурними суцвіттями, які нагадують мереживо. Ця рослина походить із Європи й Західної Азії та є близьким родичем звичайної моркви, проте її основна декоративна цінність полягає у квітках. Даукус утворює пишні зонтики, що складаються з безлічі дрібних білих квіток, іноді з центральною квіткою темного кольору, яка додає контрасту.\nРослина вирощується як дворічна або багаторічна і віддає перевагу добре дренованим ґрунтам і сонячним ділянкам. Вона чудово підходить для природних садів, ландшафтних композицій і зрізу — її мереживні суцвіття додають легкості й витонченості квітковим букетам. Крім декоративного використання, даукус є важливим медоносом, приваблюючи бджіл та інших запилювачів. Його квіти символізують простоту, природну красу і гармонію.'),(51,'Квітка Дельфініум','Жовтецеві','Однорічна','50-200 см','Синій, фіолетовий, рожевий, білий','Червень-Серпень','06-01','08-31','Сонячне або напівзатінене місце, регулярний полив, родючий грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://vesnodar.com.ua/image/cache/catalog/products/flowers/semena-cvetov-delphinium-magic-fountains-sky-blue-with-white-bee-700x700.jpg','Дельфініум (Delphinium) — це висока, елегантна рослина з родини жовтецевих (Ranunculaceae), яка відома своїми стрункими квітковими колосами, вкритими яскравими квітками. Її батьківщиною є Європа, Азія та Північна Америка, і вона представлена більш ніж 300 видами, що варіюються від дикорослих трав до гібридів для декоративного вирощування. Квіти дельфініума можуть бути синіми, фіолетовими, рожевими, білими або блакитними, часто з контрастним \"оком\" у центрі. Його висота може досягати 2 метрів, що робить рослину чудовим вибором для створення вертикальних акцентів у квітниках.\nДельфініум цвіте влітку, за умови наявності добре дренованого, родючого ґрунту і сонячного місця, хоча він любить прохолодний клімат. У ландшафтному дизайні рослину використовують у міксбордерах, групових насадженнях і в букетах, де вона додає витонченості. Вона символізує легкість, радість і відкритість, що робить її популярною для прикрашання урочистих подій.'),(52,'Квітка Діантус (Гвоздика)','Гвоздичні','Квітуча','20-60 см','Рожевий, червоний, білий','Травень-Серпень','05-01','10-31','Сонячне місце, помірний полив, слабокислий грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://camellia-market.com.ua/image/cache/catalog/amarilis_diantus/img_7270-auto_width_1333.jpg','Діантус (Dianthus) — це рід квітучих рослин із родини гвоздикових (Caryophyllaceae), що включає понад 300 видів і є символом ніжності та витонченості. Його назва в перекладі з грецької означає \"божественна квітка\". Батьківщиною діантуса є Європа та Азія, а в культурі він вирощується вже тисячі років. Квіти діантуса мають характерний гвоздиковий аромат і можуть бути білими, рожевими, червоними чи пурпуровими, часто з хвилястими або зубчастими краями пелюсток. Це низькоросла рослина, яка зазвичай досягає висоти 30-50 см.\nДіантус чудово підходить для оформлення клумб, альпійських гірок, бордюрів і для вирощування в горщиках. Він любить добре дренований ґрунт, сонце та помірний полив. Ця рослина символізує любов, відданість і пристрасть, а завдяки своїй невибагливості вона є улюбленцем багатьох садівників.'),(53,'Квітка Діантус барбатус','Гвоздичні','Квітуча','30-70 см','Рожевий, білий, червоний','Травень-Липень','06-01','09-30','Регулярний полив, сонячне місце, родючий грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://raiflora.com.ua/image/cache/catalog/Dianthus/zriz/green-wicky/diantus-barbatus-green-wicky-1280.webp','Діантус барбатус (Dianthus barbatus), відомий як \"гвоздика бородата\" або \"турецька гвоздика\", є особливо популярним видом діантуса. Це дворічна або багаторічна рослина, що утворює щільні суцвіття, які складаються з безлічі дрібних квіток. Їхні відтінки варіюються від білого і рожевого до червоного, фіолетового і навіть двоколірного, часто з красивими візерунками. Діантус барбатус досягає висоти 30-60 см і має приємний аромат.\nЦя рослина є чудовим вибором для створення яскравих клумб, бордюрів і зрізу. Вона цвіте з кінця весни до середини літа, додаючи саду шарму та вишуканості. Діантус барбатус добре росте на сонячних місцях із дренованим ґрунтом і потребує помірного поливу. Символізуючи мужність, вірність і відданість, ця квітка є популярною в декоративному садівництві та у флористичних композиціях.'),(54,'Квітка Евкаліпт','Миртові','Декоративна','200-300 см','Білий, жовтий','Липень-Вересень','01-01','12-31','Сонячне місце, помірний полив, добре дренований грунт','Тропіки і субтропіки','Родючий, нейтральний','18-30°C','Середня','https://interflora.com.ua/img/400x487/01-949.png','Евкаліпт (Eucalyptus) — це рід вічнозелених дерев і кущів із родини миртових (Myrtaceae), до якого належить понад 700 видів. Батьківщиною евкаліпта є Австралія, де він домінує в багатьох природних екосистемах. Рослина вирізняється своїм швидким ростом, гладкою, часто відлущуваною корою та ароматним листям, багатим на ефірні олії. Евкаліпт відомий своїми цілющими властивостями: його ефірна олія використовується в медицині, ароматерапії та косметиці. Деякі види евкаліпта досягають висоти до 100 метрів, що робить їх одними з найвищих дерев у світі.\nУ декоративному садівництві евкаліпти висаджують як окремі акценти або для створення тіні, а їхнє листя додають у флористичні композиції завдяки витонченій формі та свіжому аромату. Евкаліпт потребує багато сонця та добре дренованого ґрунту, хоча окремі види можуть рости навіть у складних умовах. У символіці рослина асоціюється з оновленням, захистом і спокоєм.'),(55,'Квітка Еремурус','Асфоделові','Багаторічна','100-250 см','Жовтий, білий, рожевий','Червень-Липень','05-01','07-31','Сонячне місце, добре дренований грунт, мінімальний полив','Посушливі регіони','Піщаний, нейтральний','15-30°C','Низька','https://yaskrava.com.ua/image/cache/catalog/lesja/eremurus/eremurus_stenophyllus-500x500.jpg','Еремурус (Eremurus), відомий також як \"шпиляста лілія\" або \"пустельна свічка\", є багаторічною трав''янистою рослиною з родини асфоделових (Asphodelaceae). Його батьківщиною є Центральна Азія, і він славиться своїми високими, стрункими квітконосами, які можуть досягати висоти до 2 метрів. Суцвіття еремуруса складаються з безлічі дрібних зіркоподібних квіток білого, жовтого, рожевого чи оранжевого кольору. Його декоративність та витривалість зробили еремурус популярним вибором для ландшафтного дизайну.\nРослина цвіте влітку, додаючи саду вертикальної динаміки. Еремурус потребує сонячних ділянок, добре дренованого ґрунту й помірного поливу. Він чудово виглядає у змішаних клумбах або як акцентна рослина. У символіці еремурус асоціюється з витонченістю, силою та прагненням до висоти.'),(56,'Квітка Ерінгіум','Зонтичні','Декоративна','50-100 см','Блакитний, сріблястий','Липень-Серпень','06-01','09-30','Сонячне місце, добре дренований грунт, мінімальний полив','Помірні регіони','Піщаний, нейтральний','15-25°C','Середня','https://kvitka-distribution.com.ua/content/images/34/480x320l50nn0/59023708601792.jpg','Ерінгіум (Eryngium), або \"синьоголовник\", — це трав''яниста багаторічна рослина з родини зонтичних (Apiaceae), яка вирізняється своїм екзотичним виглядом. Його батьківщиною є Європа, Америка та Центральна Азія. Ерінгіум має жорсткі, колючі листя та суцвіття у формі кулі чи конуса, оточені яскравими приквітками. Забарвлення рослини варіюється від зеленуватого до яскраво-синього чи сталевого, що робить її популярною як у садах, так і у флористичних композиціях.\nЕрінгіум добре росте на сухих, сонячних ділянках із піщаним або кам''янистим ґрунтом. Він невибагливий у догляді й має тривалий період декоративності, навіть після висихання. Його часто використовують у природних садках, альпійських гірках і сухих букетах. У символіці ерінгіум означає стійкість, захист і оригінальність, що підкреслює його унікальний зовнішній вигляд.'),(57,'Квітка Еустома','Тирличеві','Сезонна','30-100 см','Білий, рожевий, синій','Червень-Жовтень','07-01','10-31','Регулярний полив, пухкий грунт, розсіяне світло','Помірні і теплі регіони','Родючий, нейтральний','18-25°C','Середня','https://gospodar.net/image/cache/catalog/0/00/000000176_eystoma_Lavandova-xW.jpg','Еустома (Eustoma), відома також як \"лізіантус\" або \"техаська дзвіночок\", є елегантною квітучою рослиною з родини тирличевих (Gentianaceae). Її батьківщина — теплі регіони Північної Америки, включаючи Мексику та Карибський басейн. Еустома відома своїми ніжними, воронкоподібними квітами, які можуть бути білими, рожевими, фіолетовими, блакитними або двоколірними. Її пелюстки нагадують троянду або мак і виглядають напрочуд витончено. Висота рослини варіюється від 30 до 100 см, залежно від сорту, що робить її універсальною для садів і квіткових композицій.\nЕустома цвіте влітку і вимагає добре дренованого ґрунту, помірного поливу і сонячного місця. Її часто вирощують у садах, на терасах або як кімнатну рослину. Завдяки своїй довговічності у зрізаному вигляді еустома є улюбленою квіткою флористів, особливо для весільних букетів. Вона символізує вдячність, елегантність і захоплення.'),(58,'Квітка Еуфорбія','Молочайні','Декоративна','50-200 см','Зелений, жовтий','Травень-Липень','06-01','09-30','Сонячне місце, мінімальний полив, піщаний грунт','Посушливі регіони','Піщаний, нейтральний','15-30°C','Низька','https://agronomist.in.ua/wp-content/uploads/2014/02/8796-998.jpg','Еуфорбія (Euphorbia), або \"молочай\", — це великий і різноманітний рід рослин із родини молочайних (Euphorbiaceae), що включає понад 2000 видів. Еуфорбія може бути трав''янистою рослиною, чагарником або навіть деревом, залежно від виду. Її батьківщина охоплює різні кліматичні зони, від тропіків до пустель. Рослина відома своїм молочним соком, який містить латекс і може бути токсичним. Декоративні еуфорбії славляться різноманіттям форм і кольорів, включаючи яскраво-зелені, червонуваті або сіруваті відтінки.\nЕуфорбія вирощується як декоративна рослина в садах і на підвіконнях. Вона невибаглива у догляді, потребує добре дренованого ґрунту та сонячного місця. У флористиці її використовують як екзотичний акцент у композиціях. Еуфорбія символізує захист, витривалість і адаптивність завдяки своїй здатності виживати в найсуворіших умовах.'),(59,'Квітка Ехеверія','Товстолисті','Сезонна','5-20 см','Рожевий, зелений','Березень-Травень','01-01','12-31','Сонячне місце, мінімальний полив, піщаний грунт','Посушливі регіони','Піщаний, нейтральний','15-25°C','Низька','https://cdn.asterias.od.ua/images/402/402-1-91-700x683.jpg','Ехеверія (Echeveria) — це рід сукулентів із родини товстолистих (Crassulaceae), що походить із Мексики та Центральної Америки. Ехеверія відома своїми м''ясистими листками, які утворюють акуратні розетки. Листя може мати різноманітне забарвлення — зелене, сірувато-блакитне, рожеве або пурпурове, часто з матовим або восковим покриттям, яке захищає рослину від висихання. Розмір розеток варіюється від кількох сантиметрів до більш ніж 30 см у діаметрі.\nЕхеверія цвіте у весняно-літній період, випускаючи довгі квітконоси з маленькими дзвіночкоподібними квітами. Вона невибаглива, ідеально підходить для кімнатного вирощування, альпінаріїв або як частина композицій із сукулентів. Рослина потребує мінімального поливу, добре дренованого ґрунту та багато світла. Ехеверія символізує стійкість, вічну красу та гармонію, що робить її популярною як декоративну рослину для сучасного інтер''єру.'),(60,'Квітка Жасмін','Маслинові','Багаторічна','150-300 см','Білий, кремовий','Червень-Вересень','06-01','09-30','Сонячне або напівзатінене місце, помірний полив, родючий грунт','Теплі регіони','Родючий, нейтральний','18-30°C','Середня','https://cluboz.net/wp-content/uploads/2023/09/zhasmin.jpg','Жасмін (Jasminum) — це рід вічнозелених або листопадних чагарників і ліан із родини маслинових (Oleaceae), що налічує понад 200 видів. Його батьківщиною є теплі регіони Євразії та Африки. Жасмін відомий своїми дрібними білими, жовтими або рожевими квітками, які виділяють надзвичайно ніжний і приємний аромат, особливо у вечірній час. Ця рослина символізує чистоту, любов і духовну красу, а її ефірна олія є цінним компонентом парфумерії.\nЖасмін часто вирощують як декоративну рослину в садах або на балконах. Він любить добре дренований ґрунт, теплі умови й багато світла. Деякі види використовують для виробництва ароматного жасминового чаю або в лікувальних цілях. У дизайні саду жасмін додає романтичності завдяки своєму аромату і витонченим квіткам.'),(61,'Квітка Жоржина','Айстрові','Сезонна','30-200 см','Рожевий, червоний, жовтий, білий','Липень-Жовтень','07-01','10-31','Регулярний полив, добре дренований грунт, сонячне місце','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://upload.wikimedia.org/wikipedia/commons/9/91/DahliaDahlstarSunsetPink.jpg','Жоржини (Dahlia) — це бульбові багаторічники з родини айстрових (Asteraceae), родом із Мексики. Вони мають величезну різноманітність форм, розмірів і кольорів квіток: від простих ромашкоподібних до пишних, багатопелюсткових куль. Жоржини можуть досягати висоти від 30 см до 2 метрів, залежно від сорту, і цвітуть із середини літа до пізньої осені, створюючи яскраве шоу в саду.\nРослини невибагливі у догляді, але потребують добре дренованого ґрунту, регулярного поливу та сонячних ділянок. Їх висаджують у клумби, міксбордери або використовують для створення ефектних зрізів. Жоржини символізують розкіш, вдячність і силу духу, а їхня краса зробила їх однією з найулюбленіших садових квіток.'),(62,'Квітка Зантедескія (Кала)','Ароїдні','Багаторічна','30-100 см','Білий, рожевий, жовтий','Травень-Серпень','04-01','07-31','Помірний полив, слабокислий грунт, розсіяне світло','Теплі регіони','Слабокислий, родючий','18-25°C','Середня','https://interflora.com.ua/img/400x487/51-633.png','Кала (Zantedeschia), також відома як \"зантедескія\" або \"калла-лілія\", є витонченою трав''янистою багаторічною рослиною з родини ароїдних (Araceae). Її батьківщина — тропічна Африка. Кала привертає увагу своїми великими, лійкоподібними приквітками, які можуть бути білого, жовтого, рожевого, помаранчевого, фіолетового або чорного кольору. У центрі квітки знаходиться жовтий або кремовий початок. Листя кали стрілоподібне, часто з декоративними плямами.\nЦя рослина цвіте переважно навесні й влітку, добре росте на сонячних або напівтіньових ділянках, у вологих і добре дренованих ґрунтах. Кали вирощують у садах, на терасах або як кімнатні квіти. Вони також популярні у флористиці, особливо для створення весільних букетів завдяки своїй символіці чистоти, краси та елегантності. У культурі кала часто асоціюється з повагою і відданістю.'),(63,'Квітка Календула','Айстрові','Однорічна','20-60 см','Жовтий, оранжевий','Травень-Вересень','06-01','10-31','Сонячне місце, помірний полив, легкий грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://cdn.botanichka.ru/wp-content/uploads/2011/08/Calendula2.jpg','Календула (Calendula), або \"нагідки\", — це яскрава квітуча рослина з родини айстрових (Asteraceae), що родом із Середземномор''я. Її яскраво-жовті або помаранчеві квіти, схожі на маленькі сонця, цінують не лише за декоративність, а й за лікувальні властивості. Календула використовується в медицині, косметології та кулінарії завдяки своїм протизапальним, антисептичним і загоювальним властивостям. Її квіти часто додають у чаї або як натуральний барвник у стравах.\nЦе невибаглива рослина, яка цвіте з ранньої весни до осені, якщо регулярно видаляти відцвілі квітки. Вона добре росте на сонячних ділянках із помірно родючим ґрунтом і потребує лише мінімального догляду. У садах календула чудово виглядає в бордюрах, клумбах і квітниках, а також відома своєю здатністю відлякувати шкідників. Символічно ця квітка асоціюється з вірністю, теплотою та здоров’ям.'),(64,'Квітка Капсикум','Пасльонові','Декоративна','20-50 см','Червоний, жовтий, оранжевий','Червень-Вересень','09-01','12-31','Сонячне місце, регулярний полив, слабокислий грунт','Теплі регіони','Слабокислий, нейтральний','18-30°C','Середня','https://cdn.asterias.od.ua/images/138/138-7-47-700x643.jpg','Капсикум (Capsicum), або \"декоративний перець\", — це рід рослин із родини пасльонових (Solanaceae), який включає як харчові сорти (наприклад, болгарський перець), так і декоративні види. Його яскраві плоди, які можуть бути червоними, жовтими, оранжевими, зеленими, пурпуровими або білими, використовуються для прикрашання інтер''єру або саду. Хоча ці плоди їстівні, декоративні сорти часто мають гострий смак і вирощуються переважно через свою естетичну привабливість.\nКапсикум легко вирощується в горщиках, контейнерах або відкритому ґрунті. Він любить сонячні місця, регулярний полив і добре дренований ґрунт. У теплих кліматах капсикум може цвісти та плодоносити протягом усього року. Символічно ця рослина уособлює енергію, сміливість і пристрасть, що підкреслюється яскравістю її плодів.'),(65,'Квітка Картамус','Айстрові','Сезонна','30-100 см','Жовтий, оранжевий','Липень-Вересень','06-01','09-30','Сонячне місце, мінімальний полив, піщаний грунт','Посушливі регіони','Піщаний, нейтральний','15-30°C','Низька','https://rozy.com.ua/img/scif1_add/spr_noms/8/8985/8985_71_20230909100237_5449.jpg','Картамус (Carthamus), відомий також як \"шафранка фарбувальна\" або \"дикий шафран\", — це однорічна трав''яниста рослина з родини айстрових (Asteraceae), родом із Середземномор''я, Індії та Центральної Азії. Її квітки золотистого, оранжевого або червоного кольору використовуються для виробництва натуральних барвників, косметики та кулінарії. Насіння картамуса є цінним джерелом олії, яка використовується в кулінарії та як кормова добавка.\nЦе невибаглива рослина, що добре росте на сонячних, сухих ділянках із бідним ґрунтом. Висота картамуса може досягати 30-100 см. Його квітки зберігають свою декоративність навіть у сухому вигляді, тому часто використовуються у флористиці. Символічно картамус асоціюється з витривалістю, радістю та достатком, що підкреслює його яскравий і стійкий характер.'),(66,'Квітка Кверкус','Букові','Декоративна','200-300 см','Зелений','Червень-Липень','05-01','08-31','Помірний полив, добре дренований грунт, сонячне місце','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://cs1.livemaster.ru/storage/33/e9/b7e052755a7f4eb4b4fd670d79yp--tsvety-i-floristika-kverkus.jpg','Кверкус (Quercus), або \"дуб\", — це рід великих і довговічних дерев із родини букових (Fagaceae), що налічує близько 600 видів. Його батьківщиною є Північна півкуля, де дуби є символами сили, витривалості та стабільності. Дуби можуть виростати до 30-40 метрів у висоту і жити сотні, а іноді й тисячі років. Їхні міцні, розлогі крони надають густу тінь, а жолуді, які вони продукують, є важливим джерелом харчування для багатьох видів тварин.\nДуби мають як декоративну, так і практичну цінність. Їх використовують у парках і садах, а деревина високо цінується в будівництві, меблевій справі та виноробстві (для виготовлення бочок). Дуби невибагливі, але потребують сонячного місця і добре дренованого ґрунту. У культурі дуб є символом мудрості, довголіття та могутності.'),(67,'Квітка Кермек','Свинчаткові','Декоративна','30-100 см','Білий, рожевий, фіолетовий','Липень-Серпень','06-01','09-30','Сонячне місце, мінімальний полив, піщаний грунт','Посушливі регіони','Піщаний, нейтральний','15-30°C','Низька','https://interflora.com.ua/img/400x487/11-615.png','Кермек (Limonium), або \"статиця\", — це трав''яниста або напівчагарникова багаторічна рослина з родини кермекових (Plumbaginaceae), що походить із середземноморських і посушливих регіонів. Його квітки дрібні, зібрані у великі, пухкі суцвіття, і мають широкий спектр кольорів: білий, рожевий, фіолетовий, жовтий або синій. Завдяки своїй стійкості до висихання квіти кермека популярні у флористиці, особливо для створення сухих букетів.\nКермек добре росте на сонячних, сухих ділянках із бідним ґрунтом. Він не потребує складного догляду, але вимагає захисту від надмірної вологості. Рослина цвіте влітку й на початку осені, додаючи саду яскравих кольорових акцентів. У символіці кермек асоціюється з міцністю, стійкістю та пам''яттю.'),(68,'Квітка Клематіс','Жовтецеві','Сезонна','200-400 см','Білий, рожевий, фіолетовий, синій','Травень-Вересень','05-01','09-30','Сонячне або напівзатінене місце, регулярний полив, родючий грунт','Помірні регіони','Родючий, слабокислий','10-25°C','Середня','https://plants-club.s3.eu-central-1.amazonaws.com/50255/conversions/I7gpbaqUs0QPLWsnr7wSZgg4B6fGjA0X-large.jpg','Клематіс (Clematis) — це багаторічна витка рослина з родини жовтецевих (Ranunculaceae), що включає понад 300 видів. Його батьківщиною є Європа, Азія та Америка. Клематіс відомий своїми великими, часто ефектними квітами, які можуть бути білими, рожевими, червоними, синіми, фіолетовими або двоколірними. Рослина здатна прикрасити будь-який сад завдяки своїй здатності обвивати опори, утворюючи квітучі стіни, арки або альтанки.\nКлематіс цвіте з весни до осені залежно від сорту. Він любить добре дренований, багатий на поживні речовини ґрунт, багато сонця та регулярний полив. Однак коріння потребує затінення, щоб уникнути пересихання. Клематіс символізує креативність, розкіш і прагнення досягти висоти, що підкреслюється його виткими стеблами й пишним цвітінням.'),(69,'Квітка Кніфофія','Асфоделові','Багаторічна','50-150 см','Червоний, помаранчевий, жовтий','Червень-Серпень','06-01','09-30','Сонячне місце, помірний полив, дренований грунт','Теплі регіони','Дренований, нейтральний','15-30°C','Середня','https://cdn.asterias.od.ua/images/466/466-1-9-700x682.jpg','Кніфофія (Kniphofia), або \"тритома\", — це екзотична трав''яниста багаторічна рослина з родини асфоделових (Asphodelaceae), родом із Південної Африки. Вона відома своїми яскравими, вертикальними суцвіттями, що нагадують смолоскипи. Квітки, зібрані в густі колосоподібні суцвіття, змінюють свій колір під час цвітіння — від червоного або помаранчевого до жовтого. Ця яскрава рослина досягає висоти 60-150 см і цвіте влітку або на початку осені.\nКніфофія чудово підходить для створення акцентів у саду, особливо біля водойм. Вона любить сонячні ділянки, добре дренований ґрунт і помірний полив. Завдяки своєму тропічному вигляду та яскравим кольорам, кніфофія додає екзотики до будь-якого садового ландшафту. Символічно вона уособлює енергію, теплоту й силу.'),(70,'Квітка Конвалія','Лілійні','Багаторічна','15-30 см','Білий','Травень-Червень','05-01','06-15','Напівтінь, помірний полив, легкий грунт','Помірні регіони','Легкий, нейтральний','10-20°C','Середня','https://yaskravaklumba.com.ua/image/catalog/stativideo/Articles/landysh-2.jpg?1488813616750','Конвалія (Convallaria majalis) — це ніжна багаторічна трав''яниста рослина з родини холодкових (Asparagaceae), поширена в Європі, Азії та Північній Америці. Її дрібні дзвіночкоподібні білі або рожевуваті квітки з приємним ароматом зібрані у витончені кисті. Конвалія цвіте навесні, утворюючи килими на вологих, затінених ділянках лісу чи саду.\nРослина цінується за свою простоту й чарівність, часто використовується в декоративних композиціях і весільних букетах. Конвалія невибаглива, але любить затінок і помірно вологий ґрунт. Вона символізує чистоту, скромність і відродження, а також є квітковим символом травня в багатьох країнах.'),(71,'Квітка Кортадерія','Злакові','Квітуча','100-300 см','Білий, сріблястий, рожевий','Серпень-Жовтень','08-01','10-31','Сонячне місце, мінімальний полив, добре дренований грунт','Помірні регіони','Дренований, нейтральний','15-25°C','Низька','https://green-edem.com.ua/content/images/3/480x480l50nn0/cortaderiya_rosea-16637285990521.jpg','Кортадерія (Cortaderia selloana), або \"пампасна трава\", — це велика декоративна багаторічна рослина з родини злакових (Poaceae), родом із Південної Америки. Її висота може досягати 2-3 метрів, а довгі вузькі листки утворюють пишний кущ. Восени кортадерія випускає високі квітконоси з пухнастими, пірчастими суцвіттями білого, сріблястого, рожевого або кремового кольору, які чудово виглядають у саду чи ландшафтних композиціях.\nКортадерія любить сонячні місця, добре дренований ґрунт і стійка до посухи. Вона додає ефектності садовим ландшафтам, використовується для створення фокусних точок або як жива огорожа. У флористиці суцвіття пампасної трави популярні для декору інтер''єру завдяки своїй довговічності. Символічно кортадерія асоціюється з витонченістю, силою та свободою.'),(72,'Квітка Космея','Айстрові','Однорічна','50-150 см','Рожевий, білий, червоний','Червень-Вересень','06-01','09-30','Сонячне місце, помірний полив, легкий грунт','Помірні регіони','Легкий, нейтральний','15-25°C','Середня','https://florium.ua/media/catalog/product/cache/1/file/9df78eab33525d08d6e5fb8d27136e95/k/o/kosmeya_visokorosla_sumish.jpg','Космея (Cosmos), або \"космос\", — це однорічна або багаторічна трав''яниста рослина з родини айстрових (Asteraceae), що походить із тропічних і субтропічних регіонів Америки. Космея відома своїми ніжними, схожими на ромашки квітами, які можуть бути білими, рожевими, червоними, пурпуровими або жовтими. Її листя тонке, ажурне, нагадує мереживо, що надає рослині легкості й витонченості.\nЦя рослина цвіте з середини літа до осені, невибаглива, добре переносить посуху та зростає навіть у бідному ґрунті. Космею часто висаджують у клумби, міксбордери або природні сади, де вона додає яскравих акцентів. У культурі космея символізує гармонію, красу та простоту, підкреслюючи своїм виглядом природну елегантність.'),(73,'Квітка Котінус','Ананасові','Декоративна','100-500 см','Зелений, червоний','Травень-Червень','06-01','09-30','Сонячне місце, помірний полив, піщаний грунт','Теплі регіони','Піщаний, нейтральний','15-30°C','Середня','https://cdn.27.ua/799/f1/15/7205141_2.jpeg','Котінус (Cotinus), або \"перуковий кущ\", — це декоративний чагарник або невелике дерево з родини анакардієвих (Anacardiaceae), родом із Європи, Азії та Північної Америки. Він привертає увагу своїм кольоровим листям (зеленим, пурпуровим чи оранжево-червоним, залежно від сорту) та незвичайними пухнастими суцвіттями, які нагадують легку хмару чи перуку. Цвітіння відбувається влітку, додаючи в саду повітряності та загадковості.\nКотінус любить сонячні місця, добре дренований ґрунт і може переносити посуху. Він чудово виглядає як солітер або в групових насадженнях, особливо в осінній період, коли його листя стає ще яскравішим. Символічно котінус асоціюється з унікальністю та витонченістю, адже його декоративний вигляд завжди приковує увагу.'),(74,'Квітка Краспедія','Айстрові','Декоративна','30-70 см','Жовтий','Липень-Вересень','06-01','10-31','Сонячне місце, мінімальний полив, піщаний грунт','Посушливі регіони','Піщаний, нейтральний','15-30°C','Низька','https://interflora.com.ua/img/400x487/01-750.png','Краспедія (Craspedia), або \"барабанні палички\", — це багаторічна трав''яниста рослина з родини айстрових (Asteraceae), що походить із Австралії та Нової Зеландії. Вона відома своїми яскраво-жовтими кулястими суцвіттями, розташованими на довгих прямостоячих стеблах, які досягають висоти до 70-90 см. Завдяки своєму незвичайному вигляду краспедія додає сучасного шарму будь-якій квітковій композиції.\nЦя рослина невибаглива, любить сонце, добре дренований ґрунт і переносить посуху. Її квіти довговічні й не втрачають декоративності навіть у сухому вигляді, тому краспедію часто використовують у флористиці для створення букетів і декору. Символічно краспедія асоціюється з радістю, оптимізмом і креативністю, підкреслюючи своєю формою і кольором грайливість і стиль.'),(75,'Квітка Лаванда','Ясноткові','Багаторічна','30-80 см','Фіолетовий, синій','Червень-Серпень','06-01','08-31','Сонячне місце, мінімальний полив, добре дренований грунт','Теплі регіони','Дренований, лужний','15-30°C','Низька','https://olis.com.ua/wp-content/uploads/lavanda-01-1904.jpeg','Лаванда (Lavandula) — це ароматна багаторічна напівчагарникова рослина з родини глухокропивових (Lamiaceae), що походить із регіонів Середземномор''я. Її вузькі сріблясті листки та дрібні квітки, зібрані в густі колосоподібні суцвіття, варіюються від ніжно-бузкового до насичено-фіолетового кольору. Лаванда відома своїм заспокійливим ароматом, який використовується в парфумерії, косметології та ароматерапії.\nЦвіте з червня до серпня і привертає до себе бджіл та метеликів. Вона любить сонячні місця, добре дренований ґрунт і не потребує рясного поливу. Лаванду висаджують у декоративних бордюрах, альпінаріях і садових композиціях, а також сушать для створення букетів і саше. Символічно лаванда асоціюється зі спокоєм, чистотою й витонченістю.'),(76,'Квітка Лагурус','Злакові','Декоративна','20-50 см','Білий, кремовий','Серпень-Жовтень','06-01','09-30','Сонячне місце, мінімальний полив, піщаний грунт','Посушливі регіони','Піщаний, нейтральний','15-25°C','Низька','https://odarka-kvitka.com.ua/content/images/26/480x480l50nn0/lahurus625-50029303593128.jpg','Лагурус (Lagurus ovatus), або \"заячий хвіст\", — це однорічна трав''яниста рослина з родини злакових (Poaceae), що походить із регіонів Середземномор''я. Вона отримала свою назву завдяки м''яким і пухнастим суцвіттям овальної форми, які нагадують хвостики зайців. Суцвіття лагуруса зазвичай білого, кремового або сріблястого кольору, що робить рослину популярною у флористиці.\nЛагурус вирощують у сонячних місцях із добре дренованим ґрунтом. Рослина невибаглива, стійка до посухи і цвіте влітку. Його суцвіття використовують для створення букетів, прикрас та інтер''єрного декору. Символічно лагурус асоціюється з ніжністю, легкістю й природною красою.'),(77,'Квітка Латірус','Бобові','Однорічна','50-200 см','Рожевий, білий, фіолетовий','Червень-Серпень','06-01','09-30','Сонячне місце, регулярний полив, родючий грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://donpion.ua/static/media/uploads/product/One_flower/latirus/.thumbnails/img_1474_dp.jpg/img_1474_dp-472x472.jpg','Латірус (Lathyrus), або \"запашний горошок\", — це витка однорічна або багаторічна рослина з родини бобових (Fabaceae), родом із Середземномор''я. Її яскраві, ароматні квіти нагадують метеликів і мають широкий спектр кольорів — від білого та рожевого до червоного, синього та фіолетового. Латірус активно цвіте з початку літа до осені, додаючи чарівності квітникам і живоплотам.\nЦя рослина добре росте на сонячних або злегка затінених ділянках із пухким, родючим ґрунтом. Латірус використовують для вертикального озеленення, висаджуючи його біля арок, парканів чи шпалер. Символічно запашний горошок асоціюється з ніжністю, вдячністю й радістю, уособлюючи літній настрій і романтику.'),(78,'Квітка Ледерварен','Папоротеві','Декоративна','30-70 см','Зелений','Не цвіте','01-01','12-31','Напівтінь, регулярний полив, вологий грунт','Тропічні регіони','Вологий, слабокислий','18-25°C','Висока','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcReo8jnbupdjhRhXZIl4qJLkMHz1doqUovmhg&s','Ледерварен (Leatherfern, Rumohra adiantiformis) — це багаторічна папороть із родини щитникових (Dryopteridaceae), поширена в тропічних і субтропічних регіонах. Вона відома своїм блискучим, темно-зеленим листям, яке виглядає шкіряним, звідси й назва. Листя ледерварену довговічне, що робить його популярним елементом у флористиці для додавання пишності та структури до букетів.\nЛедерварен любить вологий, добре дренований ґрунт, частковий затінок і вологе повітря, що робить його чудовим вибором для вирощування в теплицях або як кімнатну рослину. Рослина невибаглива й має декоративний вигляд навіть без квітів. Символічно ледерварен уособлює витривалість, силу та елегантність, завдяки своєму вічнозеленому листю.'),(79,'Квітка Леукадендрон','Протейні','Декоративна','100-300 см','Жовтий, червоний, зелений','Червень-Серпень','06-01','10-31','Сонячне місце, мінімальний полив, піщаний грунт','Теплі регіони','Піщаний, нейтральний','15-30°C','Низька','https://camellia-market.com.ua/image/cache/catalog/ekzotika/leukadendronkrasnyj-auto_width_1333.jpg','Леукадендрон (Leucadendron) — це рід багаторічних чагарників або невеликих дерев із родини протейних (Proteaceae), що походить із Південної Африки. Вони вирізняються своїм яскравим декоративним листям і суцвіттями, які можуть мати різноманітні відтінки: від зеленого й жовтого до червоного та оранжевого. Суцвіття леукадендрона часто використовуються у флористиці через їхню довговічність і незвичайний вигляд.\nРослина любить сонячні місця, добре дренований ґрунт і помірний полив. Її вирощують у декоративних садах або контейнерах, додаючи тропічної естетики до ландшафтів. Символічно леукадендрон асоціюється з силою, стабільністю й екзотичною красою, що підкреслює його унікальний вигляд і природну витривалість.'),(80,'Квітка Леукоспермум','Протейні','Декоративна','50-200 см','Червоний, помаранчевий, жовтий','Березень-Серпень','05-01','09-30','Сонячне місце, мінімальний полив, добре дренований грунт','Теплі регіони','Дренований, слабокислий','15-30°C','Низька','https://upload.wikimedia.org/wikipedia/commons/1/10/Leucospermum_erubescens.jpg','Леукоспермум (Leucospermum) — це квітучий чагарник із родини протейних (Proteaceae), також родом із Південної Африки. Його ефектні, сферичні суцвіття нагадують голчасті кулі, що бувають жовтого, помаранчевого, червоного чи рожевого кольору. Леукоспермум цвіте навесні та влітку, привертаючи увагу не лише людей, а й запилювачів, таких як птахи й комахи.\nЦя рослина полюбляє сонячні місця, піщаний або кам''янистий ґрунт і добре переносить посуху. Її вирощують у садах, альпінаріях або контейнерах, а також широко використовують у флористиці завдяки незвичайній текстурі суцвіть. Символічно леукоспермум уособлює унікальність, яскравість і життєву силу, що відображає його незвичайний і тропічний вигляд.'),(81,'Квітка Лунарія','Капустяні','Однорічна','30-90 см','Білий, фіолетовий','Травень-Липень','06-01','08-31','Сонячне місце, помірний полив, родючий грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://florasad-agro.com.ua/uploads/products/prod_917-1505721343-37811.jpg','Лунарія (Lunaria), або \"монетниця\", — це декоративна трав''яниста рослина з родини хрестоцвітих (Brassicaceae), родом із Європи. Вона відома своїми незвичайними, прозорими, схожими на монетки плодами-лопатями, які залишаються декоративними навіть після цвітіння. Квітки лунарії можуть бути фіолетовими, рожевими або білими, зібрані у витончені суцвіття, які з''являються навесні.\nЛунарія добре росте на сонячних або злегка затінених ділянках із родючим ґрунтом. Її часто використовують у декоративних композиціях, сухих букетах та садових клумбах. Символічно лунарія асоціюється з чесністю, щедрістю та місячною красою, що підкреслюється її блискучими плодами.'),(82,'Квітка Лілія','Лілійні','Багаторічна','50-150 см','Білий, рожевий, жовтий, червоний','Червень-Серпень','06-01','08-31','Сонячне або напівзатінене місце, регулярний полив, слабокислий грунт','Помірні регіони','Слабокислий, родючий','15-25°C','Середня','https://interflora.com.ua/img/400x487/51-068.png','Лілія (Lilium) — це рід багаторічних трав''янистих рослин із родини лілійних (Liliaceae), який включає понад 100 видів. Лілії славляться своїми великими, вишуканими квітками у формі чаші або дзвоника, які мають широкий спектр кольорів: білий, жовтий, помаранчевий, рожевий, червоний і навіть бордовий. Їхній аромат наповнює сади, особливо влітку, коли вони активно цвітуть.\nЛілії люблять добре дренований, пухкий ґрунт і сонячні ділянки. Вони використовуються в ландшафтному дизайні, для зрізу в букети та в ритуальних композиціях. Символічно лілії асоціюються з чистотою, величчю та невинністю, будучи квітковими емблемами багатьох культур і традицій.'),(83,'Квітка Магнолія','Магнолієві','Багаторічна','300-900 см','Білий, рожевий, кремовий','Березень-Квітень','04-01','06-30','Сонячне місце, помірний полив, родючий слабокислий грунт','Теплі регіони','Родючий, слабокислий','10-25°C','Середня','https://ekomalina.com.ua/wp-content/uploads/2014/11/%D1%81%D1%83%D0%BB%D0%B0%D0%BD%D0%B6%D0%B01.jpg','Магнолія (Magnolia) — це рід дерев і чагарників із родини магнолієвих (Magnoliaceae), що походить із Північної та Південної Америки, Азії. Вона відома своїми великими, запашними квітами, які можуть бути білими, рожевими, пурпуровими чи кремовими. Квітки з''являються ранньою весною, часто ще до розпускання листя, надаючи саду неймовірно розкішного вигляду.\nМагнолії люблять добре дренований, кислий ґрунт і сонячні місця з легким затінком. Ці рослини використовують у ландшафтному дизайні як солітери чи акценти. Символічно магнолія уособлює шляхетність, красу та гармонію, а також є символом жіночності та витонченості.'),(84,'Квітка Малина (листя)','Розові','Сезонна','50-150 см','Зелений (листя)','Не цвіте (листя)','06-01','08-31','Сонячне або напівтіньове місце, регулярний полив, слабокислий грунт','Помірні регіони','Родючий, слабокислий','10-25°C','Середня','https://www.growhow.in.ua/wp-content/uploads/2019/07/article85427.jpg.pagespeed.ce.LERrAwZk-B.jpg','Листя малини (Rubus idaeus) — це частина багаторічного чагарника з родини розових (Rosaceae), широко відомого завдяки своїм солодким ягодам. Листя малини має темно-зелений верхній бік і сріблясто-зелений з нижньої сторони, злегка зубчасті краї. Воно містить безліч корисних речовин, таких як вітаміни, антиоксиданти та дубильні речовини, що робить його популярним у народній медицині.\nЛистя зазвичай збирають і висушують для приготування чаю, який відомий своїми заспокійливими та зміцнювальними властивостями, особливо корисними для жінок. Чагарники малини легко вирощувати на добре освітлених ділянках із родючим ґрунтом, що робить її улюбленою культурою в садівництві. Символічно малина асоціюється з родинним добробутом і затишком.'),(85,'Квітка Малус','Розові','Декоративна','300-800 см','Рожевий, білий','Квітень-Травень','04-01','06-30','Сонячне місце, регулярний полив, добре дренований грунт','Помірні регіони','Дренований, нейтральний','10-25°C','Середня','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQw_7RO3sOQELat6ZschO5DX4MTx7YPd2g6BQ&s','Малус (Malus), або \"яблуня\", — це рід листопадних дерев і чагарників із родини розових (Rosaceae), поширений у помірному кліматі. Дерева малуса мають декоративне та плодове значення. Навесні яблуні вкриваються білосніжними, рожевими чи червонуватими квітами, що додають саду особливого шарму. Восени вони дарують смачні плоди, які можуть бути їстівними або декоративними, залежно від виду.\nМалус любить сонячні ділянки, помірно зволожений ґрунт і догляд, що включає обрізання для формування крони. Декоративні яблуні висаджують у парках і садах для створення акцентів, тоді як плодові сорти вирощують для збору врожаю. Символічно яблуня асоціюється з родючістю, мудрістю та спокусою, будучи однією з ключових рослин у багатьох міфах і легендах.'),(86,'Квітка Матіола','Капустяні','Однорічна','30-80 см','Рожевий, фіолетовий, білий','Червень-Серпень','05-01','09-30','Сонячне місце, регулярний полив, легкий грунт','Помірні регіони','Легкий, нейтральний','15-25°C','Середня','https://camellia-market.com.ua/image/cache/catalog/img_2550%281%29-auto_width_1333.jpg','Матіола (Matthiola), або \"левкої\", — це трав''яниста або напівчагарникова рослина з родини капустяних (Brassicaceae), яка походить із Середземномор''я. Матіола відома своїми ароматними квітками, що розкриваються в сутінках і наповнюють повітря солодким запахом. Квітки можуть бути простими чи махровими, різних кольорів: від білого та рожевого до фіолетового й пурпурного.\nМатіолу вирощують як однорічну або багаторічну декоративну рослину в квітниках, на бордюрах і в контейнерах. Вона невибаглива до умов вирощування, але віддає перевагу сонячним ділянкам і помірному поливу. Символічно матіола асоціюється з витонченістю, романтикою та спокоєм, роблячи її улюбленицею для нічних садів і букетів.'),(87,'Квітка Молюцела','Глухокропивові','Однорічна','50-100 см','Зелений','Червень-Серпень','06-01','10-31','Сонячне місце, мінімальний полив, піщаний грунт','Теплі регіони','Піщаний, нейтральний','15-30°C','Низька','https://upload.wikimedia.org/wikipedia/commons/e/e1/Molucella_%28284561049%29.jpg','Молюцела (Moluccella laevis), або \"ірландські дзвіночки\", — це однорічна трав''яниста рослина з родини губоцвітих (Lamiaceae), що походить із Середземномор''я та Західної Азії. Вона відома своїми декоративними, зелено-зеленими чашечками, які утворюють високе, елегантне стебло. Справжні квітки молюцели — крихітні й білуваті, заховані всередині цих чашечок.\nМолюцела цвіте влітку й любить сонячні місця, добре дренований ґрунт і помірний полив. Її висота та унікальний вигляд роблять її популярною для створення флористичних композицій і додавання акцентів до садових клумб. Символічно молюцела асоціюється з благополуччям і гармонією, що підкреслюється її спокійним зеленим кольором.'),(88,'Квітка Монстера','Аронникові','Декоративна','100-300 см','Не цвіте часто','Не цвіте (у кімнатах)','01-01','12-31','Напівтінь, регулярний полив, вологий грунт','Тропічні регіони','Родючий, слабокислий','18-25°C','Висока','https://vikna.tv/wp-content/uploads/2023/05/09/monstera.jpg','Монстера (Monstera) — це тропічна ліана з родини ароїдних (Araceae), родом із Центральної та Південної Америки. Вона знаменита своїми великими, блискучими, перфорованими листками, які створюють ефектну декоративну крону. Монстера часто використовується як кімнатна рослина завдяки невибагливості й здатності очищувати повітря.\nЦя рослина полюбляє яскраве розсіяне світло, вологий ґрунт і високу вологість. Її можна вирощувати як ґрунтопокривну рослину або підтримувати на опорах, дозволяючи їй розвиватися вертикально. Символічно монстера асоціюється з силою, адаптивністю та екзотикою, будучи символом тропічної природи.'),(89,'Квітка Мускарі','Лілійні','Багаторічна','10-30 см','Синій, фіолетовий, білий','Квітень-Травень','03-01','05-31','Сонячне місце, помірний полив, добре дренований грунт','Помірні регіони','Дренований, нейтральний','10-20°C','Середня','https://upload.wikimedia.org/wikipedia/commons/5/54/Muscari_botryoides.JPG','Мускарі (Muscari), або \"мишачий гіацинт\", — це багаторічна цибулинна рослина з родини спаржевих (Asparagaceae), яка походить із регіонів Середземномор''я та Центральної Азії. Її компактні, витончені суцвіття складаються з крихітних дзвоникоподібних квітів синього, фіолетового, білого або рожевого кольору. Мускарі зазвичай цвіте ранньою весною, додаючи яскравості саду після зими.\nЦя рослина невибаглива, швидко розмножується, утворюючи густі килими. Її вирощують у квітниках, бордюрах або альпінаріях, а також використовують у зрізаних композиціях. Символічно мускарі асоціюється з відродженням, свіжістю й надією, символізуючи прихід весни та пробудження природи.'),(90,'Квітка Мімоза','Бобові','Декоративна','200-600 см','Жовтий','Січень-Квітень','02-01','04-30','Сонячне місце, мінімальний полив, дренований грунт','Теплі регіони','Дренований, нейтральний','15-30°C','Низька','https://yarmarka-dekora.com/image/cache//data/2022/13.02.22/52_74cv-1-700x700.jpg','Мімоза (Mimosa pudica) — це тропічна багаторічна рослина з родини бобових (Fabaceae), яка походить із Центральної та Південної Америки. Найбільше відома своєю унікальною властивістю — листя мімози згортається й \"засинає\" при дотику або вібраціях, завдяки чому її ще називають \"сором''язливою рослиною\". Мімоза також має ніжні рожеві чи лавандові пухнасті квітки, що надають їй декоративної привабливості.\nВона любить сонячні місця, легкий дренований ґрунт і помірний полив. Мімозу часто вирощують як декоративну рослину в кімнатних умовах чи теплицях. Символічно мімоза асоціюється з чутливістю, ніжністю та делікатністю. У культурі її гілочки часто дарують жінкам як символ весни й поваги, наприклад, під час святкування 8 Березня.'),(91,'Квітка Міскантус','Злакові','Декоративна','100-300 см','Сріблястий, рожевий','Серпень-Жовтень','08-01','10-31','Сонячне місце, мінімальний полив, дренований грунт','Помірні регіони','Дренований, нейтральний','15-25°C','Низька','https://lizgard.com.ua/assets/galleries/27627/miskantus-kitajskij-gracilllimus.jpg','Міскантус (Miscanthus) — це багаторічна трав''яниста рослина з родини злакових (Poaceae), яка походить із Азії та Африки. Міскантус цінується за свою високу декоративність: його довге вузьке листя й витончені волотисті суцвіття, які можуть бути сріблястими, рожевими або золотистими, надають саду природної динаміки. Ця рослина особливо ефектна восени, коли листя набуває відтінків червоного, жовтого й бронзового кольорів.\nМіскантус любить сонячні місця, добре дренований ґрунт і терпимо ставиться до періодичної посухи. Його використовують для оформлення декоративних клумб, створення живоплотів чи в якості солітера в ландшафтному дизайні. Символічно міскантус асоціюється з витривалістю, гармонією та природною красою.'),(92,'Квітка Нарцис','Амаралісові','Багаторічна','30-60 см','Жовтий, білий','Березень-Квітень','03-01','05-31','Сонячне місце, помірний полив, легкий добре дренований грунт','Помірні регіони','Родючий, слабокислий','10-20°C','Середня','https://upload.wikimedia.org/wikipedia/commons/7/71/Yellow_daffodils_-_floriade_canberra.jpg','Нарцис (Narcissus) — це багаторічна цибулинна рослина з родини амарилісових (Amaryllidaceae), яка походить із Європи та Північної Африки. Нарциси відомі своїми яскравими квітами у формі чаші або коронки, що зазвичай бувають білими, жовтими або кремовими, іноді з контрастними відтінками в центрі. Цвіте ранньою весною, часто стаючи одним із перших вісників тепла.\nРослина невибаглива, любить сонячні або злегка затінені місця та добре дренований ґрунт. Її використовують для створення квіткових бордюрів, весняних клумб чи для натуралізації в садах. Символічно нарцис асоціюється з відродженням, новим початком і весною, а в міфології він є символом краси та самозакоханості, що відображено в легенді про Нарциса.'),(93,'Квітка Нелюмбо','Лотосові','Декоративна','50-150 см','Рожевий, білий','Липень-Серпень','07-01','09-30','Сонячне місце, постійно вологий грунт або вода, родючий мул','Тропічні та теплі регіони','Родючий, вологий','25-35°C','Висока','https://lh6.googleusercontent.com/proxy/xlLEf-G59qrHtyYOm-8dduFBGGTw4h2RgSpe6_xMQWDYyAN-xwob42DwEHJI4ZraV_Mt9metqT-YPstJOj0Vj_zhdG7_lLNnKQgT4LUe-UFiP-JKpuxkSd3_pyd2','Нелюмбо (Nelumbo), або \"лотос\", — це водяна багаторічна рослина з родини лотосових (Nelumbonaceae), яка росте в стоячих або повільно текучих водоймах Азії, Австралії та Америки. Лотос має великі округлі листки, що плавають на поверхні води або підносяться над нею, та вражаючі квітки з ніжними пелюстками рожевого, білого чи кремового кольору. Його плоди — конічні капсули, які використовуються як декоративний елемент або для споживання.\nЛотос символізує чистоту, духовність і відродження у багатьох культурах, оскільки його квітка підіймається з мулистої води бездоганно чистою. Рослина полюбляє теплий клімат і потребує глибокого, поживного ґрунту в водоймі. У садах її використовують для створення декоративних ставків, а квіти — для флористичних композицій.'),(94,'Квітка Неріне','Амаралісові','Багаторічна','30-50 см','Рожевий, білий, червоний','Вересень-Жовтень','09-01','11-30','Сонячне місце, помірний полив, легкий піщаний грунт','Теплі регіони','Піщаний, нейтральний','15-25°C','Середня','https://florium.ua/media/catalog/product/cache/1/file/9df78eab33525d08d6e5fb8d27136e95/_/1/_1_23_2.jpg','Неріне (Nerine) — це багаторічна цибулинна рослина з родини амарилісових (Amaryllidaceae), яка походить із Південної Африки. Її витончені квітки, що нагадують зірки, розташовані на високих безлистих стеблах і мають яскраві кольори: рожевий, червоний, білий або помаранчевий. Неріне цвіте восени, додаючи барв у сад саме тоді, коли інші рослини вже завершують свій сезон.\nРослина любить сонячні ділянки, добре дренований ґрунт і помірний полив. Її вирощують у садах, контейнерах або використовують для зрізання в букети. Символічно неріне асоціюється з жіночністю, ніжністю й радістю, а також є символом тепла й світла в холодні місяці.'),(95,'Квітка Нобіліс (ялинка)','Соснові','Декоративна','500-2000 см','Зелений','Не цвіте','11-01','12-31','Сонячне місце, помірний полив, добре дренований грунт','Помірні регіони','Дренований, нейтральний','5-20°C','Середня','https://flores-shop.com.ua/wp-content/uploads/2021/12/el-nobilis.jpg','Нобіліс (Abies nobilis), або \"пихта благородна\", — це вид хвойних дерев із родини соснових (Pinaceae), родом із Північної Америки. Це вічнозелене дерево відоме своїм симетричним конусоподібним ростом, м''якими голками блакитно-зеленого кольору та ароматною деревиною. Нобіліс часто використовують як різдвяне дерево завдяки його тривалому збереженню голок після зрізання.\nЦя пихта любить прохолодний клімат, добре дренований ґрунт і потребує достатньо простору для повноцінного розвитку. У ландшафтному дизайні її висаджують як солітер або для створення алей. Символічно нобіліс уособлює сталість, міцність і благородство, будучи асоціацією зі святковими традиціями та родинним теплом.'),(96,'Квітка Нігела','Жовтецеві','Однорічна','20-50 см','Синій, білий, рожевий','Травень-Серпень','06-01','09-30','Сонячне місце, регулярний полив, легкий дренований грунт','Помірні регіони','Легкий, нейтральний','15-25°C','Середня','https://florasad-agro.com.ua/uploads/products/prod_946-1506115673-664896.jpg','Нігела (Nigella), або чорнушка, — це рід однорічних трав''янистих рослин із родини Жовтецевих (Ranunculaceae). Найвідоміший вид — чорнушка посівна (Nigella sativa), яка відома своїми декоративними квітами й ароматним насінням. Квіти нігели ніжні, мають синій, білий або рожевий колір, з характерними тонкими листочками, що нагадують мереживо. Після цвітіння утворюються декоративні коробочки з насінням, які також додають рослині привабливості.\nНігела використовується як декоративна рослина в садах, особливо для створення природних квітників і альпінаріїв. Її насіння мають пряний смак і аромат, тому широко застосовуються в кулінарії та медицині. У народній медицині чорнушку використовують для покращення травлення й зміцнення імунітету. Символічно нігела асоціюється з чистотою й гармонією.'),(97,'Квітка Озотамнус','Айстрові','Декоративна','50-100 см','Рожевий, білий','Червень-Серпень','06-01','10-31','Сонячне місце, помірний полив, піщаний грунт','Теплі регіони','Піщаний, нейтральний','15-30°C','Середня','https://camellia-market.com.ua/image/cache/catalog/importn/cvety/ozotamnus-auto_width_1333.jpg','Озотамнус (Ozothamnus) — це рід вічнозелених чагарників із родини Айстрових (Asteraceae), які природно ростуть в Австралії та Новій Зеландії. Ці рослини вирізняються маленькими, сріблястими або зеленими листочками й крихітними квітами, зібраними в щільні суцвіття. Квіти озотамнуса зазвичай білого, кремового або рожевого відтінку, вони довго тримаються й зберігають декоративність після висихання, завдяки чому рослина дуже популярна у флористиці.\nОзотамнус часто використовується в садівництві для створення бордюрів, альпійських гірок і композицій у сухих умовах. Він стійкий до посухи, любить добре дреновані ґрунти й сонячні місця. У флористиці суцвіття озотамнуса застосовуються для виготовлення сухих букетів і вінків. Його природна краса символізує витонченість і стійкість.'),(98,'Квітка Оксіпеталум','Кутрові','Декоративна','30-60 см','Блакитний, білий','Червень-Вересень','06-01','09-30','Сонячне місце, регулярний полив, добре дренований грунт','Теплі регіони','Дренований, нейтральний','15-25°C','Середня','https://rozy.com.ua/img/scif1_add/spr_noms/5/5171/5171_57_20220717094556_5477.jpg','Оксіпеталум (Oxypetalum) — це рід тропічних багаторічників із родини Кутрових (Apocynaceae), що походить із Південної Америки. Найпопулярніший вид — оксіпеталум блакитний (Oxypetalum coeruleum), відомий також як \"квітка кохання\". Ця рослина цінується за свої яскраві небесно-блакитні або бірюзові квіти у формі зірки, які мають приємний аромат і довгий період цвітіння. Вона створює витончені кущі, які додають яскравих акцентів будь-якому саду.\nОксіпеталум вирощують як декоративну рослину для садів і контейнерів. Він любить теплий клімат, сонячні місця й добре дренований ґрунт. У флористиці оксіпеталум використовується як екзотична складова весільних і романтичних букетів. Його символічне значення пов’язане з ніжністю, чистотою й вічним коханням, завдяки чому він користується популярністю у весільній флористиці.'),(99,'Квітка Онцидіум','Орхідні','Декоративна','30-80 см','Жовтий, коричневий, рожевий','Березень-Травень','09-01','11-30','Розсіяне світло, регулярний полив, спеціальний субстрат для орхідей','Тропічні регіони','Субстрат для орхідей','18-25°C','Висока','https://lorashen.ua/static/media/uploads/product/Rasteniya/.thumbnails/dsc_0415.png/dsc_0415-0x600.png','Онцидіум (Oncidium) — це рід орхідей із родини Орхідних (Orchidaceae), який налічує понад 300 видів. Походять ці орхідеї з тропічних і субтропічних регіонів Південної та Центральної Америки. Їх часто називають \"танцюючими ледіями\" завдяки формі квіток, які нагадують маленьких фігурок у танці. Квіти онцидіума зазвичай жовтого, оранжевого, коричневого або рожевого кольору, часто з плямистим малюнком. Деякі види мають ніжний аромат, що додає їм особливого шарму.\nОнцидіуми чудово підходять для вирощування вдома, але потребують багато світла, помірної вологості й правильного поливу. У флористиці вони використовуються як екзотичні акценти в букетах і композиціях, символізуючи витонченість і життєву енергію. Завдяки своєму тривалому цвітінню й вишуканому вигляду онцидіуми є одними з найулюбленіших орхідей для колекціонерів.'),(100,'Квітка Орнітогалум','Лілійні','Багаторічна','30-80 см','Білий, зелений','Квітень-Травень','04-01','06-30','Сонячне місце, помірний полив, дренований грунт','Помірні регіони','Дренований, нейтральний','10-20°C','Середня','https://florium.ua/media/catalog/product/cache/1/file/9df78eab33525d08d6e5fb8d27136e95/o/r/ornithogalum_umbellatum-4.jpg','Орнітогалум (Ornithogalum), або \"пташине молоко\", — це рід трав''янистих багаторічників із родини Гіацинтових (Hyacinthaceae). Рослина родом із Європи, Азії та Африки й відома своїми елегантними суцвіттями у вигляді зонтиків або китичок із численними білими або кремовими зірчастими квітами. У деяких видів квіти мають зеленувату смужку вздовж пелюсток, що надає їм унікального вигляду. Орнітогалум цвіте довго й виглядає дуже ефектно як у саду, так і в букетах.\nУ флористиці орнітогалум використовується як універсальна квітка завдяки своїй стійкості після зрізання й здатності доповнювати як класичні, так і сучасні композиції. Він символізує чистоту, надію та новий початок, тому часто зустрічається у весільних букетах. У садівництві орнітогалум цінують за невибагливість: він добре росте на сонці або в напівтіні та пристосовується до різних типів ґрунту.'),(101,'Квітка Панікум','Злакові','Декоративна','50-120 см','Зелений, золотистий','Серпень-Вересень','07-01','10-31','Сонячне місце, помірний полив, дренований грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://yaskravaklumba.com.ua/image/cache/catalog/mnogoletniki/dekorativni_travi_zlaki/panikumnorthwind-500x500.jpg','Панікум (Panicum), або просо, — це рід багаторічних трав із родини Злакових (Poaceae), який включає понад 450 видів. Панікум вирощується як кормова й декоративна рослина. У декоративному садівництві особливо популярні види з легкими, ажурними волотями, які надають композиціям ніжності та повітряності. Забарвлення листя та суцвіть панікуму може варіюватися від зеленого до пурпурового або навіть червонуватого.\nЦя рослина невибаглива, легко пристосовується до різних кліматичних умов і добре переносить посуху. У флористиці панікум використовується для створення природних або сучасних букетів і як текстурний елемент у композиціях. Він додає букетам легкості, гармонійно поєднуючись із великими яскравими квітами. Символічно панікум асоціюється зі спокоєм і природністю, що робить його популярним вибором у трендовій екостилістиці.'),(102,'Квітка Папавер (Мак)','Макові','Сезонна','30-90 см','Червоний, білий, рожевий','Травень-Червень','05-01','07-31','Сонячне місце, помірний полив, добре дренований грунт','Помірні регіони','Супіщаний, нейтральний','10-25°C','Середня','https://image.jimcdn.com/app/cms/image/transf/none/path/sdc0073d89a34328a/image/ie3eae5c2a4277d12/version/1568992736/image.jpg','Папавер (Papaver), або мак, — це рід трав''янистих рослин із родини Макових (Papaveraceae), який включає близько 100 видів. Маки вирізняються своїми великими, ніжними квітами з яскравими червоними, помаранчевими, рожевими або білими пелюстками й темним центром. Цвітіння маків є коротким, але дуже ефектним, а їхні декоративні коробочки з насінням залишаються цікавими елементами саду навіть після в''янення квітів.\nУ садівництві мак використовується для створення яскравих квітників і природних композицій. Він добре росте на сонячних ділянках і в ґрунті з гарним дренажем. Мак має значну культурну й символічну роль: у багатьох культурах він асоціюється з пам''яттю, спокоєм і сном. Деякі види маку, як-от мак снодійний (Papaver somniferum), використовуються в медицині для виготовлення знеболювальних препаратів.'),(103,'Квітка Протея','Протеєві','Декоративна','50-200 см','Рожевий, червоний, білий','Круглорічно','06-01','10-31','Сонячне місце, мінімальний полив, піщаний грунт','Теплі регіони','Піщаний, кислий','15-30°C','Низька','https://upload.wikimedia.org/wikipedia/commons/5/5d/Cynaroides_-_sb616.JPG','Протея (Protea) — це рід квіткових рослин із родини Протейних (Proteaceae), які природно ростуть у Південній Африці. Протеї відомі своїми незвичайними, екзотичними квітками, які можуть бути різних розмірів і форм. Їхні суцвіття складаються з сотень дрібних квіток, оточених великими яскравими приквітками. Колірна палітра протей включає рожевий, червоний, помаранчевий, жовтий і кремовий. Вони символізують зміни, мужність і трансформацію завдяки своїй здатності пристосовуватися до суворих умов.\nПротеї популярні у флористиці завдяки своїй стійкості, текстурі й виразному вигляду. У композиціях вони виступають акцентними квітками, додаючи екзотичної елегантності. У садівництві протеї вирощують у теплих регіонах із добре дренованим ґрунтом, оскільки вони чутливі до надмірної вологості.'),(104,'Квітка Протея королівська','Протеєві','Декоративна','100-300 см','Рожевий, кремовий','Круглорічно','05-01','09-30','Сонячне місце, мінімальний полив, піщаний дренований грунт','Теплі регіони','Піщаний, кислий','15-30°C','Низька','https://flores-shop.com.ua/wp-content/uploads/2022/12/proteya-bila-korolivska.jpeg','Протея королівська (Protea cynaroides) — один із найвідоміших і найефектніших видів протей, який також є національною квіткою Південної Африки. Її велике суцвіття, схоже на корону, може досягати до 30 см у діаметрі. Приквітки мають різноманітні відтінки — від рожевого до кремового й червоного. Ця квітка вражає не лише своїм розміром, але й витривалістю: вона може рости в посушливих регіонах і відновлюватися після пожеж завдяки своїм потужним кореням.\nПротея королівська є справжнім символом розкоші й сили, тому її часто використовують у весільній флористиці, урочистих композиціях і як центральний елемент у букетах. Вона довго зберігає декоративний вигляд після зрізання, а також може висушуватися, зберігаючи свої форми та кольори, що робить її унікальним вибором для сухих композицій. У культурному контексті ця квітка символізує велич і стійкість.'),(105,'Квітка Прунус','Розові','Декоративна','200-600 см','Рожевий, білий','Квітень-Травень','03-01','05-31','Сонячне місце, помірний полив, родючий грунт','Помірні регіони','Родючий, нейтральний','10-20°C','Середня','https://newflora.ru/wp-content/uploads/2021/04/Prunus-triloba-Multiplex.jpg3_-scaled-1.jpg','Прунус (Prunus) — це рід рослин із родини Розових (Rosaceae), який включає понад 400 видів, зокрема вишні, сливи, персики, мигдаль і абрикоси. Ці дерева та чагарники цінуються як за декоративні якості, так і за смачні плоди. Декоративні види та сорти прунуса, як-от сакура, відомі своїм пишним весняним цвітінням. Їхні квіти, які зазвичай бувають білими, рожевими або червоними, створюють чарівні пейзажі під час масового цвітіння.\nПрунус широко використовується в садівництві для створення декоративних алей, живоплотів і акцентних посадок. Його плоди є важливими як у кулінарії, так і в харчовій промисловості. Крім того, дерево символізує весну, відродження й красу, особливо в японській культурі, де сакура є національним символом.'),(106,'Квітка Півонія','Півонієві','Багаторічна','60-120 см','Рожевий, червоний, білий','Травень-Червень','05-01','07-15','Сонячне місце, регулярний полив, родючий грунт','Помірні регіони','Родючий, слабокислий','10-25°C','Середня','https://svitroslyn.ua/upload/medialibrary/d22/d22347d83601d2f860bc7587028cc681.jpg','Півонія (Paeonia) — це рід багаторічних трав''янистих рослин і чагарників із родини Півонієвих (Paeoniaceae), який включає понад 30 видів. Півонії відомі своїми великими, яскравими квітами, що мають безліч пелюсток і приємний аромат. Забарвлення квітів варіюється від білого до рожевого, червоного, жовтого й бордового. Їхній пишний вигляд робить півонії одними з найулюбленіших садових квітів і головних акцентів у весільних та святкових букетах.\nПівонії невибагливі, але потребують сонячних ділянок і багатого на поживні речовини ґрунту. У культурі вони символізують багатство, процвітання, романтику й щасливий шлюб. У китайській традиції півонія вважається \"королевою квітів\" і символом честі й величі. Окрім декоративної ролі, півонії мають і лікувальні властивості: їхні корені та квіти використовуються в народній медицині.'),(107,'Квітка Піттоспорум','Піттоспорові','Декоративна','100-300 см','Зелений, білий','Травень-Липень','01-01','12-31','Сонячне місце, помірний полив, добре дренований грунт','Теплі регіони','Дренований, нейтральний','15-25°C','Середня','https://flowers.ua/images/Flowers/articles/582-img-2.jpg','Піттоспорум (Pittosporum) — це рід вічнозелених дерев і чагарників із родини Піттоспорових (Pittosporaceae), який включає близько 200 видів. Ці рослини природно ростуть у тропічних і субтропічних регіонах Азії, Австралії та Океанії. Піттоспорум має щільне, блискуче листя, яке може бути однотонним зеленим або з декоративною облямівкою. Дрібні квіти рослини мають приємний аромат і з’являються навесні, але в декоративному садівництві піттоспорум цінується здебільшого за своє листя.\nПіттоспорум широко використовується для створення живоплотів, бордюрів і в якості акцентної рослини в саду. У флористиці його листя додає текстури та контрасту в букетах і композиціях. Рослина невибаглива, добре переносить стрижку, що робить її популярним вибором для ландшафтного дизайну. Символічно піттоспорум асоціюється із стабільністю, гармонією й надійністю, що відображає його витривалий і універсальний характер.'),(108,'Квітка Пієріс','Вересові','Декоративна','50-150 см','Білий, рожевий','Березень-Квітень','03-01','05-31','Сонячне місце, помірний полив, кислий грунт','Помірні регіони','Кислий, родючий','10-20°C','Середня','https://landshaft.info/14111-thickbox_default/pieris-japonica-little-heath.jpg','Пієріс (Pieris) — це рід вічнозелених чагарників із родини Вересових (Ericaceae), який походить із гірських районів Азії, Північної Америки та Карибського басейну. Пієріс відомий своїм декоративним листям, яке змінює колір у міру розвитку, і красивими білими або рожевими дзвоникоподібними квітами, зібраними в гроноподібні суцвіття. Цвітіння припадає на весну, додаючи саду ніжності та свіжості. Особливістю рослини є її здатність зберігати декоративність протягом усього року.\nПієріс ідеально підходить для садів у стилі японського або природного ландшафту, добре росте в кислих ґрунтах і напівтіні. Рослина стійка до хвороб і потребує мінімального догляду, що робить її улюбленою серед садівників. Символічно пієріс уособлює чистоту, гармонію й природну красу, завдяки чому часто використовується для створення спокійних, елегантних садів.'),(109,'Квітка Ранункулюс','Жовтецеві','Квітуча','20-50 см','Рожевий, білий, жовтий, червоний','Квітень-Червень','03-01','06-30','Сонячне місце або півтінь, помірний полив, добре дренований грунт','Помірні регіони','Родючий, нейтральний','10-20°C','Середня','https://flowersliss.com.ua/image/cache/catalog/ran4-500x500.jpg','Ранункулюс (Ranunculus), або жахлик, — це рід квіткових рослин із родини Жовтецевих (Ranunculaceae), який налічує понад 400 видів. Найвідоміший представник — ранункулюс азійський (Ranunculus asiaticus), який широко використовується у флористиці. Ці рослини мають яскраві, пишні квіти з численними пелюстками, які нагадують мініатюрні троянди або півонії. Колірна гама включає білий, жовтий, помаранчевий, рожевий, червоний і навіть бордовий відтінки. Завдяки довгому періоду цвітіння й універсальності ранункулюс став улюбленою квіткою весільних букетів і композицій.\nРанункулюс вирощують як декоративну рослину в садах, на клумбах і в контейнерах. Він любить сонячні місця, легкий ґрунт і регулярний полив. У флористиці символізує романтичність, ніжність і витонченість, що робить його популярним для створення букетів на особливі випадки.'),(110,'Квітка Рубус','Розові','Декоративна','50-300 см','Рожевий, білий','Червень-Липень','06-01','08-31','Сонячне місце, помірний полив, родючий грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Rubus_ursinus_10689.JPG/1200px-Rubus_ursinus_10689.JPG','Рубус (Rubus), або ожина, — це рід рослин із родини Розових (Rosaceae), до якого належать кущі з їстівними плодами, як-от малина, ожина та логанова ягода. Рубус має гнучкі стебла, вкриті шипами, складні листки й білі або рожеві квіти, які цвітуть навесні. Після цвітіння утворюються ароматні плоди, що складаються з багатьох маленьких соковитих кістянок.\nРубус цінується як за декоративні властивості, так і за корисні плоди, багаті на вітаміни й антиоксиданти. Його вирощують як у промислових масштабах, так і в домашніх садах. У ландшафтному дизайні використовують ожину для створення живоплотів або декорування ділянок із нерівним рельєфом. Символічно рубус асоціюється із силою, захистом і родючістю, а його плоди уособлюють багатство природи.'),(111,'Квітка Рудбекія','Айстрові','Сезонна','30-90 см','Жовтий, оранжевий','Липень-Вересень','07-01','10-31','Сонячне місце, помірний полив, дренований грунт','Помірні регіони','Родючий, нейтральний','15-30°C','Середня','https://zelenabuhta.com.ua/wp-content/uploads/2023/01/got2-38.png','Рудбекія (Rudbeckia) — це рід квіткових рослин із родини Айстрових (Asteraceae), який налічує понад 20 видів. Рудбекію часто називають \"чорноока Сюзанна\" через її характерний темний центр квітки, оточений яскравими жовтими, помаранчевими або червоними пелюстками. Її квіти мають променисту форму й цвітуть із середини літа до осені, додаючи яскравих барв у квітники. Рослина невибаглива, добре переносить посуху й чудово підходить для сонячних ділянок.\nРудбекія широко використовується в декоративному садівництві для створення природних клумб і як основа для міксбордерів. У флористиці її зрізані квіти додають композиціям яскравості й динаміки. Символічно рудбекія асоціюється з енергією, життєрадісністю та стійкістю, що робить її улюбленою для літніх і осінніх букетів.'),(112,'Квітка Рускус','Спаржеві','Декоративна','50-100 см','Зелений','Немає','01-01','12-31','Сонячне місце або півтінь, мінімальний полив, дренований грунт','Помірні регіони','Дренований, нейтральний','10-25°C','Середня','https://sharm24.com.ua/images/detailed/13/ruskus-3.jpg','Рускус (Ruscus), або миший терен, — це рід вічнозелених чагарників із родини Холодкових (Asparagaceae). Найпопулярнішим видом у флористиці є рускус італійський (Ruscus hypophyllum), який має щільне, блискуче зелене \"листя\" (філокладії, які насправді є видозміненими пагонами). Рускус цінується за свою довговічність, витривалість і універсальність у букетах.\nУ флористиці рускус використовується як декоративна зелень для створення об’ємності, текстури й контрасту в композиціях. Він добре поєднується як із яскравими, так і з пастельними квітами. Завдяки своїй невибагливості рускус символізує витривалість, гармонію та силу природи. У садівництві його вирощують як декоративну рослину, яка добре росте в затінених ділянках і не потребує особливого догляду.'),(113,'Квітка Салал','Вересові','Декоративна','50-150 см','Зелений','Немає','01-01','12-31','Півтінь, помірний полив, кислий грунт','Помірні регіони','Кислий, дренований','10-20°C','Середня','https://camellia-market.com.ua/image/cache/catalog/importn/cvety/salal-auto_width_1333.jpg','Салал (Gaultheria shallon) — це вічнозелений чагарник із родини Вересових (Ericaceae), який природно росте в лісах Північної Америки. Салал має шкірясте, блискуче зелене листя й дрібні білі або рожеві дзвоникоподібні квіти, які цвітуть навесні. Після цвітіння утворюються їстівні темно-сині ягоди, які часто використовують для приготування джемів і десертів.\nУ флористиці салал є незамінним елементом завдяки своїй здатності зберігати свіжий вигляд тривалий час. Його листя додає букетам пишності, об’ємності й природної текстури. Салал символізує стабільність, надійність і зв’язок із природою, що робить його популярним у сучасних композиціях в еко-стилі. У садівництві салал вирощують як декоративну рослину, що добре пристосовується до кислих ґрунтів і часткового затінення.'),(114,'Квітка Сангвісорба','Розові','Багаторічна','50-120 см','Червоний, рожевий','Червень-Серпень','06-01','09-30','Сонячне місце, регулярний полив, родючий грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://luckyflowers.com.ua/storage/files/Sanguisorba/Sanguisorba%20officinalis/Sanguisorba_officinalis_x.jpg','Сангвісорба (Sanguisorba) — це рід трав''янистих багаторічників із родини Розових (Rosaceae), який налічує близько 30 видів. Ці рослини часто вирощують у декоративних садах завдяки їхнім елегантним суцвіттям-колоскам або головкам, які з''являються наприкінці літа. Квіти зазвичай дрібні, червонуваті, рожеві або кремові, але їхня незвичайна форма привертає увагу. Листя сангвісорби має витончену форму й схоже на папороть, що додає легкості й текстури композиціям.\nСангвісорба невибаглива й добре росте як на сонці, так і в напівтіні. Вона часто використовується в природному садівництві для створення луків, міксбордерів і садів у стилі прерій. У флористиці суцвіття сангвісорби додають композиціям легкості, рухливості й природної витонченості. Символічно ця рослина асоціюється зі скромністю, гармонією й природною красою.'),(115,'Квітка Сандерсонія','Лілійні','Квітуча','30-100 см','Помаранчевий, жовтий','Липень-Серпень','11-01','01-31','Сонячне місце, помірний полив, добре дренований грунт','Теплі регіони','Супіщаний, нейтральний','15-30°C','Середня','https://agronomist.in.ua/wp-content/uploads/2014/04/676-8790-0.jpg','Сандерсонія (Sandersonia), або \"Квітка китайських ліхтариків\", — це багаторічна трав''яниста рослина з родини Колхікових (Colchicaceae), яка походить із Південної Африки. Її стебла несуть ніжні дзвоникоподібні квітки жовтого або помаранчевого кольору, які нагадують мініатюрні ліхтарики. Сандерсонія цвіте влітку, створюючи яскравий і святковий вигляд, і є символом радості та тепла.\nЦя рослина вирощується переважно для зрізання й використовується у флористиці для створення елегантних і незвичайних букетів. Її квітки довго зберігають свіжість у зрізаному вигляді, що робить сандерсонію популярною серед флористів. У садівництві вона потребує добре дренованого ґрунту, багато сонця й помірного поливу. Символічно сандерсонія асоціюється зі щастям і святковим настроєм, що робить її чудовим вибором для урочистих композицій.'),(116,'Квітка Сенеціо','Айстрові','Декоративна','20-150 см','Жовтий, білий','Червень-Серпень','06-01','10-31','Сонячне місце, помірний полив, родючий грунт','Теплі регіони','Родючий, дренований','15-25°C','Середня','https://cdn.27.ua/799/a7/7d/6662013_1.jpeg','Сенеціо (Senecio), або крестовник, — це рід рослин із родини Айстрових (Asteraceae), який налічує понад 1,000 видів. До сенеціо належать як трав''янисті рослини, так і чагарники й сукуленти. Найвідоміші декоративні види, наприклад, сенеціо Роулі (Senecio rowleyanus), мають оригінальний вигляд завдяки своїм \"намистинним\" або ниткоподібним листям. Інші види, як-от крестовник пепельний (Senecio cineraria), вирізняються сріблястим листям і додають елегантності садовим композиціям.\nСенеціо широко використовується як у садівництві, так і в кімнатному озелененні. Сукулентні види цінуються за невибагливість і здатність рости в горщиках, прикрашаючи інтер’єри. У флористиці деякі види сенеціо використовуються для створення структурних елементів у букетах. Символічно сенеціо асоціюється з витривалістю, гармонією та адаптацією до будь-яких умов, що відображає його здатність рости в різних кліматичних умовах.'),(117,'Квітка Серрурія','Протеєві','Декоративна','30-80 см','Рожевий, кремовий','Липень-Жовтень','06-01','09-30','Сонячне місце, мінімальний полив, піщаний грунт','Теплі регіони','Піщаний, кислий','15-30°C','Низька','https://flower-stor.com.ua/1122-thickbox_default/serruriya.jpg','Серрурія (Serruria) — це рід рослин із родини Протейних (Proteaceae), який походить із Південної Африки. Найвідомішою є серрурія рожева (Serruria florida), яку часто називають \"квіткою ніжності\" через її витончені й пухнасті квіткові головки рожевого або кремового кольору. Її квіти мають унікальну текстуру, схожу на пір’я, що робить серрурію популярною у флористиці. Цвітіння триває тривалий час, додаючи витонченості будь-якій композиції.\nСеррурія полюбляє добре дренований піщаний ґрунт і багато сонця, тому її часто вирощують у садах середземноморського стилю. У флористиці використовується для створення ніжних букетів і як акцент у сучасних композиціях. Символічно серрурія уособлює ніжність, витонченість і романтику, що робить її ідеальним вибором для весільної флористики.'),(118,'Квітка Сетарія','Злакові','Декоративна','30-70 см','Зелений','Липень-Жовтень','07-01','09-30','Сонячне місце, помірний полив, супіщаний грунт','Помірні регіони','Супіщаний, нейтральний','15-25°C','Середня','https://dobrodar.ua/uploads/files/Products/Product_images_44800/d6ec08.jpg','Сетарія (Setaria), або щетинник, — це рід трав''янистих рослин із родини Злакових (Poaceae), до якого належать однорічники й багаторічники, що виростають на луках, у степах і садах. Сетарія відома своїми тонкими, прямостоячими стеблами й декоративними суцвіттями у вигляді м''яких колосків або щіточок, які можуть бути зеленими, золотистими чи пурпуровими. Ці суцвіття виглядають витончено й додають текстури будь-якому ландшафтному дизайну чи букету.\nУ флористиці сетарія використовується як декоративний елемент для створення об’ємності й природної динаміки. У садах її цінують за невибагливість і стійкість до посухи. Символічно сетарія асоціюється зі спокоєм, природністю й гармонією, що робить її улюбленим вибором у композиціях у стилі рустик чи бохо.'),(119,'Квітка Скабіоза','Жимолостеві','Декоративна','30-100 см','Рожевий, білий, фіолетовий','Червень-Серпень','06-01','10-31','Сонячне місце, помірний полив, родючий грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://green-edem.com.ua/content/images/46/480x480l50nn0/scabiosa_pink_diamonds-64990773236181.jpg','Скабіоза (Scabiosa) — це рід багаторічних або однорічних трав''янистих рослин із родини Жимолостевих (Caprifoliaceae). Скабіози цінуються за свої ніжні, округлі квіти, схожі на невеликі подушки, які розпускаються влітку й бувають різноманітних кольорів: білого, блакитного, рожевого, фіолетового або бордового. Її квіти приваблюють метеликів і бджіл, додаючи саду живої динаміки.\nСкабіоза широко використовується як у садівництві, так і у флористиці. У саду вона добре виглядає на клумбах і в природних міксбордерах. У букетах скабіоза додає ніжності та романтичності, добре поєднуючись із іншими квітами. Символічно ця рослина асоціюється з чистотою, любов’ю та ніжністю, що робить її популярною в букетах для особливих подій, зокрема весільних.'),(120,'Квітка Скімія','Рутові','Декоративна','50-150 см','Червоний, білий','Квітень-Травень','10-01','12-31','Півтінь, регулярний полив, кислий грунт','Теплі регіони','Кислий, дренований','10-20°C','Висока','https://cdn.asterias.od.ua/images/176/176-1-47-700x663.jpg','Скімія (Skimmia) — це рід вічнозелених кущів із родини Рутових (Rutaceae), які природно ростуть у гірських лісах Східної Азії. Найпопулярнішою є скімія японська (Skimmia japonica), яка цінується за свої щільні, блискучі зелені листя, ароматні білі або кремові квіти й яскраво-червоні ягоди, що з''являються після цвітіння. Скімія декоративна протягом усього року й є чудовим вибором для садів, контейнерів або композицій.\nЦя рослина невибаглива, добре переносить тінь і підходить для кислих ґрунтів. У флористиці гілочки скімії використовуються як декоративна зелень, додаючи букетам текстури й насиченого кольору. Символічно скімія асоціюється з родинним затишком, гармонією й достатком, що робить її популярною для новорічного декору.\n\n'),(121,'Квітка Солідаго','Айстрові','Декоративна','50-200 см','Жовтий','Серпень-Вересень','07-01','10-31','Сонячне місце, помірний полив, добре дренований грунт','Помірні регіони','Дренований, нейтральний','15-25°C','Середня','https://elflora.com.ua/files/resized/products/solidago.1200x1000w.jpg','Солідаго (Solidago), або золотушник, — це трав''яниста багаторічна рослина з родини Айстрових (Asteraceae), яка природно росте в Північній Америці та Євразії. Вона відома своїми дрібними яскраво-жовтими квітами, зібраними в розлогі волотисті суцвіття, які цвітуть наприкінці літа й восени. Солідаго додає квітникам яскравих сонячних акцентів, привертаючи увагу своїм золотистим сяйвом.\nУ флористиці солідаго використовується як наповнювач, додаючи легкості, об’ємності й теплоти букетам. Він символізує удачу, успіх і благополуччя, що робить його ідеальним вибором для подарункових композицій. У садівництві солідаго цінується за невибагливість, стійкість до посухи та привабливість для запилювачів, таких як бджоли й метелики.'),(122,'Квітка Соняшник','Айстрові','Квітуча','150-300 см','Жовтий, коричневий','Червень-Серпень','07-01','09-30','Сонячне місце, помірний полив, родючий грунт','Теплі регіони','Родючий, нейтральний','15-30°C','Середня','https://www.syngenta.ua/sites/g/files/kgtney1466/files/styles/syn_full_width_scale/public/media/image/2022/02/21/shutterstock_271249412.jpg?itok=omEGQbT9','Соняшник (Helianthus annuus) — це однорічна трав''яниста рослина з родини Айстрових (Asteraceae), яка є символом літа та радості. Соняшник має великі, яскраво-жовті квіти з темним диском у центрі, який складається з насіння. Ця рослина походить із Північної Америки, де її спочатку вирощували корінні народи як джерело їжі й олії. Соняшник відомий своєю здатністю \"слідувати за сонцем\" (геліотропізм) у молодому віці.\nУ флористиці соняшники додають композиціям яскравості, оптимізму й динаміки. Їх використовують як солітера або в поєднанні з іншими літніми квітами. Соняшник символізує життєву енергію, радість, успіх і відданість, що робить його популярним для подарункових і святкових букетів. У садівництві він також цінується за невибагливість і декоративність, а його насіння — за поживну цінність.'),(123,'Квітка Спірея','Розові','Декоративна','50-150 см','Рожевий, білий','Травень-Червень','05-01','07-31','Сонячне місце або півтінь, помірний полив, дренований грунт','Помірні регіони','Родючий, нейтральний','10-25°C','Середня','https://images.prom.ua/2834915322_w600_h600_2834915322.jpg','Спірея (Spiraea) — це рід листопадних чагарників із родини Розових (Rosaceae), який налічує понад 80 видів. Спірея цінується за свої пишні суцвіття, які можуть бути у вигляді парасольок, волотей або колосків, залежно від виду. Квіти дрібні, але численні, білого, рожевого або червоного кольору, і з’являються навесні або влітку. Спірея також має декоративне листя, яке восени набуває яскравих золотистих або багряних відтінків.\nЦя рослина невибаглива, добре переносить обрізання й чудово підходить для живоплотів, бордюрів і міксбордерів. У флористиці гілки спіреї використовуються як основа для композицій, додаючи їм легкості та витонченості. Символічно спірея асоціюється з чистотою, невинністю й вірністю, що робить її популярною для весільного декору.'),(124,'Квітка Стреліція','Стреліцієві','Квітуча','100-200 см','Помаранчевий, синій','Січень-Березень','01-01','12-31','Сонячне місце, помірний полив, піщаний грунт','Теплі регіони','Піщаний, слабокислий','20-30°C','Середня','https://flowers.ua/images/Flowers/articles/250-img-2.jpg','Стреліція (Strelitzia), відома як \"райський птах\", — це тропічна рослина з родини Стреліцієвих (Strelitziaceae), що походить із Південної Африки. Вона отримала свою назву через унікальну форму яскравих квітів, які нагадують голову птаха. Квіти стреліції зазвичай помаранчево-блакитні, але зустрічаються й білі у деяких видів. Її довге й широке зелене листя додає композиціям екзотичного вигляду.\nУ флористиці стреліція є символом екзотики, краси й свободи, часто використовується як центральний елемент у тропічних букетах або композиціях. У садівництві ця рослина цінується за свої декоративні властивості й тривале цвітіння, але потребує теплого клімату або вирощування у вазонах у приміщеннях.'),(125,'Квітка Стіфа','Злакові','Декоративна','30-100 см','Зелений, білий','Липень-Вересень','06-01','09-30','Сонячне місце, мінімальний полив, супіщаний грунт','Помірні регіони','Супіщаний, нейтральний','15-25°C','Низька','https://ukraflora.ua/image/cache/catalog/image/cache/catalog/2024/fototovary/6-43736_2-1100x1100.webp','Стіфа (Stipa), або ковила, — це рід декоративних багаторічних трав із родини Злакових (Poaceae), який налічує понад 300 видів. Ця рослина відома своїми тонкими, гнучкими стеблами й витонченими волотями, які створюють ілюзію руху навіть при найменшому подуві вітру. Ковила часто має сріблястий або золотистий відтінок, що додає їй елегантності.\nУ ландшафтному дизайні стіфа використовується для створення природних, хвилястих масивів у садах у стилі прерій або мінімалістичних композиціях. У флористиці ковила додає легкості, текстури й природної динаміки букетам, особливо в стилі бохо або рустик. Символічно стіфа асоціюється з ніжністю, витонченістю й свободою.'),(126,'Квітка Сукуленти','Різні родини','Декоративна','10-50 см','Зелений, рожевий','Немає','01-01','12-31','Яскраве світло, мінімальний полив, піщаний грунт','Теплі регіони','Піщаний, слабокислий','20-30°C','Низька','https://kapri.dn.ua/wp-content/uploads/2019/07/12/1-7.jpg','Сукуленти — це група рослин із різних ботанічних родин, які мають здатність зберігати воду у своїх стеблах, листках або корінні. Серед найпоширеніших сукулентів — алое, ехеверія, агави, хавортія, крассула та багато інших. Їхня головна особливість — м''ясисті частини, адаптовані до виживання в умовах посухи. Сукуленти вирізняються широким спектром форм, кольорів і текстур, від сріблястих і зелених до червоних або фіолетових відтінків.\nЦі рослини популярні в дизайні інтер''єрів завдяки своїй невибагливості й декоративності. Вони часто використовуються для створення міні-садків, вінків або композицій у стилі еко-декору. У флористиці сукуленти додають букетам сучасності та текстури. Символічно вони асоціюються зі стійкістю, витривалістю й довголіттям.'),(127,'Квітка Сімфорікарпус','Жимолостеві','Декоративна','50-200 см','Білий, рожевий','Серпень-Жовтень','08-01','10-31','Півтінь, регулярний полив, дренований грунт','Помірні регіони','Родючий, нейтральний','10-20°C','Середня','https://camellia-market.com.ua/image/cache/catalog/ekzotika/zelen/simforikarpusbelyj-auto_width_1333.jpg','Симфорікарпус (Symphoricarpos), або \"сніжноягідник\", — це рід листопадних чагарників із родини Жимолостевих (Caprifoliaceae), що походять із Північної Америки та Китаю. Рослина відома своїми дрібними рожевими або білими квітами, які перетворюються на круглі ягоди білого, рожевого чи пурпурного кольору, що зберігаються на гілках навіть узимку. Ягоди симфорікарпуса отруйні для людей, але приваблюють птахів.\nЦей чагарник часто використовується в живоплотах або для озеленення паркових зон завдяки своїй витривалості й декоративності. У флористиці гілочки з ягодами симфорікарпуса додають букетам текстури, кольорових акцентів і зимового настрою. Символічно він уособлює сталість, достаток і спокій.'),(128,'Квітка Троянда Садова','Розові','Квітуча','50-200 см','Різноманітні','Червень-Жовтень','06-01','10-31','Сонячне місце, регулярний полив, родючий грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://images.prom.ua/1837767896_w600_h600_1837767896.jpg','Троянда садова (Rosa spp.) — це одна з найвідоміших і найулюбленіших декоративних рослин у світі, яка має тисячолітню історію культивації. Садові троянди вирізняються широким спектром форм, розмірів і кольорів — від ніжно-білого й рожевого до насичено-червоного, жовтого або навіть синюватого відтінку. Їхні квіти можуть бути простими або махровими, із чарівним ароматом, що варіюється від легкого до насиченого.\nСадові троянди використовуються в озелененні для створення розаріїв, бордюрів або як солітери. У флористиці вони є символом любові, краси й вічності, тому часто стають головними елементами букетів, особливо на урочистостях. Троянда також асоціюється з романтикою, пристрастю й емоційною глибиною, що робить її універсальною квіткою для будь-якої нагоди.'),(129,'Квітка Троянда кущова','Розові','Квітуча','50-150 см','Різноманітні','Травень-Серпень','06-01','10-31','Сонячне місце, регулярний полив, добре дренований грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://family-flowers.com.ua/wp-content/uploads/2021/08/DSC_9234-800x800-1.jpg','Кущова троянда — це різновид троянд, які ростуть у вигляді густих кущів із численними пагонами, що можуть досягати від 50 см до 2 метрів у висоту, залежно від сорту. Кущові троянди мають багато квітів на одному стеблі, що робить їх особливо привабливими для садів і квіткових композицій. Квіти можуть бути різних кольорів і форм, від класичних до більш сучасних, а деякі сорти мають насичений аромат. У флористиці кущові троянди додають букетам об’єму, м’якості й романтичності. Вони асоціюються із затишком, природністю й вишуканістю, що робить їх популярними для прикрашання весіль.'),(130,'Квітка Троянда піоновидна','Розові','Квітуча','50-150 см','Рожевий, червоний, білий','Червень-Серпень','06-01','10-31','Сонячне місце, регулярний полив, супіщаний грунт','Теплі регіони','Супіщаний, слабокислий','15-25°C','Середня','https://viaflor.com.ua/edit/uploads/page/1983/656114493b342.jpg','Піоновидна троянда — це розкішний вид троянд, що вирізняється своєю формою квітів, які нагадують піони. Вона має махрові пелюстки, зібрані в густі шари, утворюючи об’ємний і водночас ніжний бутон. Найвідомішими представниками цієї категорії є сорти англійських троянд Девіда Остіна. Піоновидні троянди доступні в широкій палітрі кольорів: від білого та кремового до насичено-червоного чи навіть коралового. Вони часто мають приємний фруктовий або квітковий аромат. У флористиці такі троянди використовуються для створення розкішних, елегантних букетів і є символом витонченості, краси та романтики.'),(131,'Квітка Троянда піоновидна кущова','Розові','Квітуча','50-150 см','Рожевий, червоний, кремовий','Червень-Серпень','06-01','10-31','Сонячне місце, помірний полив, слабокислий грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://kamelia-shop.com.ua/_files/goods/rose/r00911/img1537.jpg','Піоновидна кущова троянда — це комбінація особливостей кущової та піоновидної троянди. Ці троянди ростуть у вигляді компактних кущів і мають густі, піоновидні квіти, які ідеально підходять для декору садів або створення букетів. Вони цвітуть багаторазово протягом сезону, мають густу структуру пелюсток і привабливий аромат. Такі троянди часто використовуються у флористиці для весільних композицій або святкових букетів, оскільки вони додають пишності й витонченості. Символічно піоновидна кущова троянда асоціюється із щастям, розкішшю й коханням.'),(132,'Квітка Тубероза','Амарилісові','Квітуча','50-120 см','Білий','Липень-Вересень','07-01','09-30','Сонячне місце, регулярний полив, родючий грунт','Теплі регіони','Родючий, слабокислий','20-30°C','Висока','https://cdn.asterias.od.ua/images/421/421-1-1-700x687.jpg','Тубероза (Polianthes tuberosa) — це багаторічна трав''яниста рослина з родини Спаржевих (Asparagaceae), відома своїми ароматними квітами. Вона має довгі стебла, на яких розташовуються ніжні білі або кремові квіти, що цвітуть із літа до осені. Її запах — солодкий, насичений, екзотичний, із нотами меду й квітів — робить туберозу однією з найпопулярніших рослин у парфумерії. У флористиці тубероза використовується для створення розкішних, елегантних букетів, особливо вечірніх композицій.\nТубероза символізує любов, пристрасність і витонченість. Її висаджують у садах для декоративності та аромату, але вона потребує теплого клімату або вирощування у вазонах у холодніших регіонах.'),(133,'Квітка Тюльпан','Лілійні','Сезонна','30-60 см','Різноманітні','Квітень-Травень','03-01','05-31','Сонячне місце, помірний полив, супіщаний грунт','Помірні регіони','Супіщаний, нейтральний','10-20°C','Середня','https://images.prom.ua/2794366226_w600_h600_2794366226.jpg','Тюльпан (Tulipa) — це рід багаторічних цибулинних рослин із родини Лілійних (Liliaceae), який налічує сотні видів і тисячі сортів. Тюльпани мають елегантні квіти чашоподібної форми, які можуть бути однокольоровими або з малюнками, в палітрі від білого й жовтого до насиченого червоного, рожевого, фіолетового й навіть чорного. Вони зацвітають навесні, додаючи яскравих барв у сади й квіткові композиції.\nТюльпани символізують весну, новий початок, любов і гармонію. Вони широко використовуються в букетах завдяки своїй універсальності й здатності підходити до будь-якого випадку. У садівництві їх висаджують у масивах, міксбордерах або контейнерах.'),(134,'Квітка Тюльпан піоновидний','Лілійні','Сезонна','30-60 см','Різноманітні','Квітень-Травень','03-01','05-31','Сонячне місце, помірний полив, супіщаний грунт','Помірні регіони','Супіщаний, слабокислий','10-20°C','Середня','https://sunrose.com.ua/productsImgs/img1051_main_l.jpg','Піоновидний тюльпан — це особливий сорт тюльпанів із махровими пелюстками, які нагадують квіти піона. Вони мають густу структуру бутона, що надає їм розкішного й святкового вигляду. Піоновидні тюльпани бувають різноманітних кольорів: від ніжно-рожевого й кремового до насичено-червоного або фіолетового. Цвітіння цих тюльпанів часто триває довше, ніж у звичайних сортів, а їхній вигляд робить їх фаворитами у флористиці.\nТакі тюльпани символізують витонченість, вишуканість і радість. У флористиці вони додають букетам об’єму й текстури, чудово поєднуючись із іншими весняними квітами. У садах піоновидні тюльпани використовують для створення розкішних квіткових композицій, які приваблюють увагу своєю незвичністю.'),(135,'Квітка Тілландсія','Бромелієві','Декоративна','10-30 см','Рожевий, червоний, зелений','Цілий рік','01-01','12-31','Яскраве розсіяне світло, мінімальний полив, добре дренований грунт','Тропічні регіони','Повітряний, з додаванням кори','20-30°C','Висока','https://floralife.com.ua/image/cache/catalog/encyclopedia/tillandsia-enc/tillandsia-enc-top-1200x900.jpg','Тілландсія (Tillandsia) — це рід епіфітних рослин із родини Бромелієвих (Bromeliaceae), який налічує понад 600 видів. Її також називають \"повітряною рослиною\", адже вона не потребує ґрунту для росту, а отримує вологу й поживні речовини з повітря за допомогою спеціальних лусочок на листках. Тілландсії мають цікаві форми — від витягнутих до розеткових — і можуть мати зелений, сріблястий або навіть фіолетовий відтінок. Вони цвітуть яскравими квітами, часто червоного, фіолетового або рожевого кольору, додаючи екзотичного вигляду.\nЦі рослини ідеально підходять для декоративного використання: їх розміщують у флораріумах, підвішують у кошиках або кріплять до дерев, каменів чи металевих конструкцій. Тілландсія символізує легкість, природність і здатність пристосовуватися до будь-яких умов.'),(136,'Квітка Танацетум','Айстрові','Квітуча','30-100 см','Жовтий, білий','Червень-Серпень','06-01','10-31','Сонячне місце, помірний полив, добре дренований грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://magicrose.ck.ua/wp-content/uploads/2023/04/tanacetum-2-min.jpg','Танацетум (Tanacetum), або пижмо, — це рід трав''янистих багаторічників із родини Айстрових (Asteraceae), що включає понад 160 видів. Танацетум відомий своїми дрібними квітами, схожими на ромашки або ґудзики, зібраними в щільні суцвіття. Квіти бувають білими, жовтими або різнокольоровими, залежно від виду. Це невибаглива рослина, яка цвіте протягом тривалого часу, додаючи легкості й природності в квітники.\nУ флористиці танацетум використовується як декоративний елемент для додавання текстури, об’єму й легкості в букети. Він символізує спокій, гармонію та природну красу. У садівництві танацетум цінують за його невибагливість і здатність відлякувати комах-шкідників.'),(137,'Квітка Тласпі','Капустяні','Декоративна','20-50 см','Зелений, білий','Травень-Червень','05-01','09-30','Помірне освітлення, регулярний полив, пухкий грунт','Теплі регіони','Супіщаний, слабокислий','15-25°C','Середня','https://camellia-market.com.ua/image/cache/catalog/ekzotika/zelen/tlaspi-auto_width_1333.jpg','Тласпі (Thlaspi), також відоме як \"монетниця\" або \"гірчиця польова\", — це трав''яниста однорічна або багаторічна рослина з родини Капустяних (Brassicaceae). Воно цінується у флористиці завдяки своїм витонченим дрібним листям і оригінальним округлим насіннєвим коробочкам, які нагадують монетки. Тласпі має свіжий зелений колір, який гармонійно доповнює будь-який букет, додаючи йому легкості та природності.\nЦя рослина популярна у сучасних флористичних композиціях у стилі рустик або бохо, оскільки вона додає свіжості й текстури. Символічно тласпі уособлює багатство, достаток і процвітання, завдяки своїй схожості з монетами. У садівництві його також цінують за невибагливість і декоративність.'),(138,'Квітка Трахеліум','Дзвоникові','Квітуча','30-90 см','Фіолетовий, білий','Липень-Серпень','06-01','09-30','Сонячне або напівтінь, регулярний полив, пухкий грунт','Теплі регіони','Родючий, слабокислий','15-25°C','Середня','https://cdn.asterias.od.ua/images/419/419-1-2-700x592.jpg','Трахеліум (Trachelium) — це трав''яниста багаторічна рослина з родини Дзвоникових (Campanulaceae), яка відома своїми густими суцвіттями з дрібних квітів. Її квіти, зазвичай фіолетового, білого або рожевого кольору, утворюють пишні кулясті парасольки, які додають композиціям об’єму й текстури. Трахеліум має тонкі стебла й ніжне листя, що створює ідеальну рамку для центральних елементів букета.\nЦя рослина символізує витонченість і гармонію, тому часто використовується у флористиці для романтичних або весільних композицій. Завдяки своїй структурі трахеліум гарно поєднується як із великими квітами, так і з дрібними деталями, додаючи букетам природної легкості.'),(139,'Квітка Троянда','Розові','Квітуча','50-200 см','Різноманітні','Травень-Жовтень','06-01','10-31','Сонячне місце, регулярний полив, родючий грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://agrarii-razom.com.ua/sites/default/files/byr/troyanda.png','Троянда (Rosa) — це класична й найулюбленіша квітка в усьому світі, яка символізує любов, красу, пристрасть і витонченість. Вона належить до родини Розових (Rosaceae) і представлена сотнями видів та тисячами сортів, які розрізняються за кольорами, формами й ароматами. Троянда буває однокольоровою або з відтінками, від білого й рожевого до насиченого червоного, жовтого чи навіть чорного кольору.\nУ флористиці троянда є універсальним вибором, який використовується в усіх видах букетів, від романтичних до урочистих. Її велика квітка часто є центральним елементом композицій, що підкреслює витонченість і розкіш. Троянда також має глибокий символізм: червона асоціюється з пристрастю, біла — з чистотою, а рожева — із ніжністю.'),(140,'Квітка Троянда Бомбастик','Розові','Квітуча','50-150 см','Рожевий','Червень-Серпень','06-01','10-31','Сонячне місце, регулярний полив, добре дренований грунт','Теплі регіони','Родючий, слабокислий','15-25°C','Середня','https://www.tsvitsad.com.ua/upload/catalog/641200a006e9c.jpg','Троянда Бомбастик (Rosa Bombastic) — це сорт кущової троянди, відомий своїми невеликими, але густими й пишними квітами. Бутони мають форму, схожу на піоновидні троянди, з багатошаровими пелюстками ніжно-рожевого або кремового відтінку. Троянда Бомбастик цінується за свою романтичну й м’яку текстуру, а також тривалу свіжість після зрізання.\nУ флористиці ці троянди ідеально підходять для весільних букетів, романтичних композицій і декору. Їх використовують як акцент або для заповнення букета, оскільки вони додають ніжності, об’єму й вишуканості. Символізм троянди Бомбастик пов’язаний із романтикою, ніжністю й витонченістю, що робить її фаворитом для особливих подій.'),(141,'Квітка Троянда Вовузелла','Розові','Квітуча','50-120 см','Персиковий','Травень-Липень','06-01','10-31','Сонячне місце, регулярний полив, родючий грунт','Теплі регіони','Родючий, слабокислий','15-25°C','Середня','https://traskovskyi.ua/files/products/vuvuzela-5-1500x1500.690x950.jpg','Троянда Вувузелла (Rosa Vuvuzela) — це розкішний сорт кущової троянди, який виділяється своєю унікальною забарвленістю й формою. Бутони мають багатошарову структуру пелюсток, що нагадує піоновидні троянди. Забарвлення квітів варіюється від ніжного персикового до рожевого з кремовими та зеленкуватими відтінками на зовнішніх пелюстках. Вувузелла вирізняється своєю тривалістю у свіжому стані та приємним легким ароматом.\nУ флористиці ця троянда є улюбленцем для весільних і романтичних композицій завдяки своєму елегантному вигляду. Вона чудово поєднується з іншими квітами та додає букетам м’якість, розкіш і витонченість. Символічно Вувузелла асоціюється з унікальністю, ніжністю й романтичним настроєм.'),(142,'Квітка Троянда Девіда Остіна','Розові','Квітуча','50-180 см','Різноманітні','Травень-Серпень','06-01','10-31','Сонячне місце, регулярний полив, добре дренований грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://lorashen.ua/static/media/uploads/product/Rose/.thumbnails/img_6558s.jpg/img_6558s-0x600.jpg','Троянда Девіда Остіна (Rosa David Austin) — це знаменитий сорт англійських троянд, створений селекціонером Девідом Остіном. Ці троянди поєднують у собі найкращі риси старовинних і сучасних сортів: густі, махрові квіти, насичений аромат і тривале цвітіння. Забарвлення варіюється від ніжно-пастельних відтінків (кремовий, рожевий) до яскравих червоних і жовтих тонів.\nДевід Остін створив троянди, які стали символом романтики й вишуканості. Вони часто використовуються у весільній флористиці, декорі святкових заходів і букетах преміум-класу. Ці троянди символізують класичну красу, елегантність і бездоганність, додаючи будь-якому букету неповторного шарму.'),(143,'Квітка Троянда Піано','Розові','Квітуча','50-150 см','Червоний','Травень-Серпень','06-01','10-31','Сонячне місце, регулярний полив, супіщаний грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://posadka.com.ua/upload/resize_cache/iblock/4a8/1088_1088_131903e01863149be97e251a4ed38558f/y2l5ed0nrrxm1hx63iz1qd6sdf7jo6vk.jpg','Троянда Піано (Rosa Piano) — це сорт троянд, який вирізняється великими, густими й округлими бутонами, що нагадують піони. Її пелюстки зібрані в гармонійні шари, утворюючи щільну, симетричну квітку. Забарвлення може бути насичено-червоним, рожевим або кремовим, що надає їй вишуканості. Особливістю Піано є її тривала свіжість після зрізання й стійкість до зовнішніх умов.\nУ флористиці троянда Піано часто використовується як центральний елемент букетів і композицій, завдяки своїй пишності та елегантності. Вона чудово підходить для весіль, романтичних подарунків або урочистих подій. Символізм цієї троянди пов’язаний із пристрастю, розкішшю й гармонією.'),(144,'Квітка Фаленопсис','Орхідні','Квітуча','20-100 см','Рожевий, білий, жовтий','Цілий рік','01-01','12-31','Помірне освітлення, висока вологість, полив теплою водою','Теплі регіони','Орхідний субстрат','18-25°C','Висока','https://www.google.com/url?sa=i&url=https%3A%2F%2Florashen.ua%2Fshop%2Fproduct%2Forheedeya-fukseeya%2F&psig=AOvVaw1kxPnT7BN22SbzsduuGXr_&ust=1735414328798000&source=images&cd=vfe&opi=89978449&ved=0CBQQjRxqFwoTCMCR_qbYyIoDFQAAAAAdAAAAABAR','Фаленопсис (Phalaenopsis) — це один із найвідоміших і найпопулярніших родів орхідей, які вирізняються своєю елегантною формою квітів і невибагливістю у догляді. Фаленопсиси зазвичай мають великі, симетричні квіти, схожі на метеликів, які розташовані на довгих квітконосах. Вони можуть мати найрізноманітніше забарвлення: біле, рожеве, жовте, фіолетове або навіть плямисте.\nЦі орхідеї цінуються за тривале цвітіння, яке може тривати кілька місяців, і здатність прикрашати будь-який інтер’єр. Фаленопсиси символізують красу, витонченість і гармонію. Вони ідеально підходять як подарунок і додають вишуканості в будь-який простір.'),(145,'Квітка Флокс','Синюхові','Квітуча','10-120 см','Рожевий, фіолетовий, білий','Червень-Вересень','07-01','10-31','Сонячне місце, регулярний полив, дренований грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Phlox_Paniculata.jpg/1200px-Phlox_Paniculata.jpg','Флокси (Phlox) — це багаторічні або однорічні трав''янисті рослини з родини Синюхових (Polemoniaceae). Вони відомі своїми яскравими й пишними суцвіттями, які складаються з безлічі дрібних квіток. Флокси можуть бути різних відтінків — білого, рожевого, червоного, фіолетового або блакитного, часто із приємним ароматом. Вони цвітуть улітку або на початку осені, додаючи барвистості квітникам.\nФлокси символізують гармонію, єдність і душевне тепло. У садівництві вони популярні завдяки своїй невибагливості й здатності прикрашати клумби, міксбордери та альпійські гірки. У флористиці їх використовують для створення барвистих, пишних букетів.'),(146,'Квітка Форзиція','Маслинкові','Сезонна','100-300 см','Жовтий','Березень-Квітень','03-01','05-31','Сонячне місце, добре дренований грунт, помірний полив','Помірні регіони','Родючий, нейтральний','10-20°C','Середня','https://garden-house.kiev.ua/uploads/product/519_4003667451.jpg','Форзиція (Forsythia) — це кущ із родини Маслинових (Oleaceae), який зацвітає одним із перших навесні. Її яскраво-жовті дзвоникоподібні квіти з’являються ще до розпускання листя, утворюючи золотисті хмари на гілках. Форзиція є символом приходу весни, пробудження природи й радості.\nЦей декоративний кущ часто використовується в ландшафтному дизайні для живоплотів, солітерних посадок або композицій у садах. У флористиці зрізані гілки форзиції додають букетам сонячності й легкості, створюючи відчуття весняного оновлення.'),(147,'Квітка Фрезія','Ірисові','Квітуча','20-50 см','Жовтий, білий, рожевий','Січень-Квітень','03-01','05-31','Сонячне або напівтінь, регулярний полив, легкий грунт','Теплі регіони','Родючий, слабокислий','15-25°C','Середня','https://camellia-market.com.ua/image/cache/catalog/importn/frezija/belajafrezija-auto_width_1333.jpg','Фрезія (Freesia) — це рід рослин з родини Ірісових (Iridaceae), який відомий своїми ароматними квітами й гарними кольорами. Фрезії мають трубчасті квіти, які зібрані в елегантні суцвіття, що можуть бути різного забарвлення — від білих і жовтих до рожевих, фіолетових, червоних і навіть двокольорових. Рослина зазвичай цвіте в кінці зими або на початку весни, додаючи яскравих фарб у цей час року.\nФрезія є дуже популярною в флористиці завдяки своєму приємному аромату та тривалому періоду цвітіння, який може тривати до кількох тижнів. У композиціях вона часто використовується для створення ніжних і елегантних букетів, особливо для весіль або святкових подій.\n\nФрезія символізує невинність, дружбу та гармонію. Її квітка також асоціюється з чистотою серця, чесністю й вірністю.'),(148,'Квітка Фрітілярія','Лілійні','Квітуча','20-150 см','Оранжевий, жовтий, червоний','Квітень-Травень','03-01','05-31','Сонячне або напівтінь, регулярний полив, пухкий грунт','Помірні регіони','Родючий, нейтральний','10-20°C','Середня','https://florium.ua/media/catalog/product/cache/1/file/9df78eab33525d08d6e5fb8d27136e95/t/o/tov-fritilarija-imperialis-aurora.jpg','Фрітілярія (Fritillaria) — це рід рослин із родини Лілійних (Liliaceae), який включає близько 100 видів, здебільшого багаторічних трав. Вони вирізняються своєю унікальною формою квітів, які часто мають дзвоникоподібну або чашоподібну структуру. Квітки фрітілярії можуть бути різних кольорів — від жовтих, білих, червоних до пурпурних і навіть з малюнками, часто в смужку або плямистих варіантах.\nФрітілярії цінуються за свою елегантність та екзотичний вигляд. Вони популярні в декоративному садівництві, додаючи витонченості та розкоші квітникам. Їх символізм пов''язаний з незвичайністю, гармонією та елегантністю.'),(149,'Квітка Фізаліс','Пасльонові','Декоративна','30-90 см','Помаранчевий','Серпень-Вересень','08-01','11-30','Сонячне місце, помірний полив, пухкий грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://freshmart.com.ua/storage/web/cache/product/109/fizalis-100-g.jpg?w=1024&h=768&fit=resize&q=80&fm=pjpg&t=1631872244&s=5ad69f964d2bdac642e8a4b70b442630','Фізаліс (Physalis) — це рід рослин з родини Пасльонових (Solanaceae), який включає як декоративні, так і їстівні види. Зазвичай фізаліс має характерні помаранчеві або червоні чашолистки, що оточують плоди у вигляді маленьких ягід. Відомий також як «ліхтарик» завдяки своїй яскраво-оранжевій оболонці, яка нагадує маленький ліхтарик. Цей рід включає як їстівні види (наприклад, фізаліс плодово-ягідний, який використовують у кулінарії), так і декоративні, що вирощуються для прикраси садів.\nФізаліс символізує захист, таємницю й процвітання. У флористиці фізаліс часто використовується як декоративний елемент, додаючи композиціям кольору та екзотичності.'),(150,'Квітка Філодендрон','Ароїдні','Декоративна','50-200 см','Зелений','Не цвіте','01-01','12-31','Помірне освітлення, висока вологість, регулярний полив','Теплі регіони','Родючий, слабокислий','18-25°C','Висока','https://sharm24.com.ua/images/detailed/16/1111.jpg','Філодендрон (Philodendron) — це рід тропічних рослин з родини Арекових (Araceae), який налічує понад 400 видів. Філодендрони відомі своїми великими, глянцевими, часто серцеподібними листками. Вони можуть бути як вічнозеленими, так і напіввічнозеленими, і ростуть у вигляді ліан або компактних кущів. Філодендрони легко адаптуються до умов дому, що робить їх популярними рослинами для вирощування в приміщеннях.\nФілодендрони зазвичай не цвітуть в умовах кімнатного вирощування, але їх декоративне листя робить їх дуже популярними в інтер’єрному дизайні. Вони символізують стабільність, довговічність і спокій.'),(151,'Квітка Хамелаціум','Миртові','Квітуча','50-200 см','Білий, рожевий, фіолетовий','Грудень-Квітень','06-01','10-31','Сонячне місце, помірний полив, легкий грунт','Теплі регіони','Родючий, слабокислий','15-25°C','Середня','https://azalya.com.ua/image/catalog/2711/img_20181108_134245-(1).jpg','Хамелаціум (Chamelaucium) — це рід квітучих рослин з родини Миртових (Myrtaceae), який включає близько 20 видів. Хамелаціум є вічнозеленим чагарником або маленьким деревом, відомим своїми дрібними, але дуже яскравими квітами, які часто бувають рожевими, білими або пурпурними. Квітки мають характерну форму, схожу на зірочки, і часто використовуються у флористиці за рахунок свого декоративного вигляду.\nЦю рослину часто вирощують як декоративну для садів або використовують у квіткових композиціях завдяки її витонченості й тривалому періоду цвітіння. Хамелаціум символізує елегантність і жіночність, а також уособлює довговічність і міцність.\n\n'),(152,'Квітка Хелеборус','Жовтецеві','Багаторічна','20-50 см','Білий, зелений, рожевий','Січень-Травень','01-01','03-31','Напівтінь, регулярний полив, родючий грунт','Помірні регіони','Родючий, слабокислий','10-20°C','Середня','https://ukraflora.ua/image/cache/catalog/image/catalog/categ/buket-s-kheleborusom.webp','Хеллеборус (Helleborus), або ж \"різдвяна роза\", — це рід багаторічних трав''янистих рослин з родини Лютикових (Ranunculaceae). Хеллеборуси відомі своїми витонченими квітами, які можуть бути білими, зеленими, рожевими або фіолетовими і зазвичай з’являються в холодну пору року, зокрема, в кінці зими або на початку весни. Квіти цієї рослини часто мають чашоподібну або майже плоску форму, що робить їх надзвичайно елегантними.\nХеллеборус символізує відродження, силу й витривалість, оскільки цвіте в холодний період, коли більшість рослин ще не починають розцвітати. Він популярний у ландшафтному дизайні, де використовується для створення весняних квітників або в композиціях, що поєднують ранні весняні квіти.'),(153,'Квітка Хризантема','Айстрові','Квітуча','30-150 см','Білий, жовтий, рожевий, червоний','Серпень-Листопад','09-01','11-30','Сонячне місце, регулярний полив, пухкий грунт','Помірні регіони','Родючий, слабокислий','15-25°C','Середня','https://rozsada.com.ua/pub/img/products/m/421_1602069892.jpg?v=20200528','Хризантема (Chrysanthemum) — це рід рослин із родини Айстрових (Asteraceae), який включає понад 200 видів. Хризантеми — одні з найпопулярніших осінніх квітів, що вирізняються великою кількістю різновидів, від дрібноквіткових до гігантських. Вони мають різноманітне забарвлення, від білих і жовтих до червоних, рожевих, фіолетових і навіть зелених відтінків. Хризантеми часто використовуються в декоративному садівництві, в тому числі для осінніх клумб і букетів.\nЦі квіти символізують довге життя, щастя й процвітання в різних культурах, зокрема в Японії та Китаї. У флористиці хризантеми часто застосовуються в композиціях для свят, осінніх букетах і як символ осіннього оновлення.'),(154,'Квітка Хіперикум','Клузієві','Декоративна','30-120 см','Жовтий','Червень-Серпень','06-01','10-31','Сонячне місце, помірний полив, нейтральний грунт','Помірні регіони','Родючий, нейтральний','15-25°C','Середня','https://camellia-market.com.ua/image/cache/catalog/importn/hiperikum/belyj/belyjhiperikum-auto_width_1333.jpg','Хіперикум (Hypericum) — це рід рослин із родини Гіперикових (Hypericaceae), до якого входить близько 400 видів. Хіперикум, або звіробій, відомий своїми яскравими квітами, що можуть бути жовтими, червоними або помаранчевими. Квітки часто мають пелюстки у вигляді зірочок і виділяються своєю декоративністю. Крім того, хіперикум має характерні ягоди, які після цвітіння набувають червоного або чорного кольору, додаючи рослині додаткової краси.\nХіперикум широко використовують у флористиці завдяки його яскравому вигляду та довговічності після зрізання. Рослина символізує стійкість, захист і позитивні емоції. Вона також має лікувальні властивості, що робить її важливою в народній медицині.'),(155,'Квітка Целозія','Амарантові','Квітуча','20-100 см','Червоний, жовтий, фіолетовий','Липень-Жовтень','06-01','09-30','Сонячне місце, регулярний полив, пухкий грунт','Теплі регіони','Родючий, слабокислий','20-30°C','Середня','https://cdn.asterias.od.ua/images/519/519-1-4-700x463.jpg','Целозія (Celosia) — це рід квітучих рослин з родини Амарантових (Amaranthaceae), який включає види з яскравими й незвичайними квітами. Целозія відома своєю характерною формою суцвіть, які можуть бути волотистими або схожими на гребінь півня. Квіти цієї рослини можуть бути червоними, жовтими, оранжевими або пурпурними і часто мають пухнасту, ворсисту текстуру. Вони додають особливої барви і текстури в квіткові композиції.\nЦелозія популярна в декоративному садівництві завдяки своїй витривалості й яскравим квітам. У флористиці її використовують для створення неповторних, барвистих композицій, і вона символізує жарку пристрасть, енергію і радощі.'),(156,'Квітка Цимбідіум','Орхідні','Квітуча','30-120 см','Рожевий, білий, зелений, жовтий','Зима-Весна','01-01','03-31','Розсіяне світло, висока вологість, регулярний полив','Теплі регіони','Орхідний субстрат','15-25°C','Висока','https://flowers.ua/images/Flowers/articles/318-img-1.jpg','Цимбідіум (Cymbidium) — це рід орхідей з родини Орхідних (Orchidaceae), що включає понад 50 видів. Цимбідіум є однією з найпопулярніших орхідей завдяки своїм великим і розкішним квітам, які можуть бути різних кольорів, від білих і зелених до червоних, жовтих і рожевих. Квіти цимбідіуму часто зібрані в довгі суцвіття, що надає їм вигляду екзотичних, величних композицій.\nЦі орхідеї є улюбленими для декору інтер’єрів, а також використовуються у флористичних композиціях для весіль, свят і урочистих подій. Цимбідіум символізує елегантність, силу та довговічність. Його квітки також асоціюються з високим статусом і витонченістю.'),(157,'Квітка Цинія','Айстрові','Квітуча','20-90 см','Червоний, жовтий, рожевий, білий','Червень-Вересень','06-01','09-30','Сонячне місце, регулярний полив, родючий грунт','Помірні регіони','Родючий, нейтральний','20-30°C','Середня','https://planti.com.ua/images/detailed/1/nasinnya-ciniya-liliput-miks-planti.jpg','Цинія (Zinnia) — це рід квітучих рослин з родини Айстрових (Asteraceae), що включає понад 20 видів. Цинії відомі своїми яскравими і різноманітними квітами, які можуть бути червоними, рожевими, жовтими, оранжевими, білими або пурпурними. Квіти мають форму кошика, складеного з численних пелюсток, що надають рослині пишного вигляду. Цинією часто прикрашають клумби і квітники, адже вона чудово переносить спекотну погоду і тривалий час цвіте.\nЦинії символізують радощі, пристрасну любов і стійкість, а також є символом довгого й щасливого життя. Їх часто використовують у флористиці для створення яскравих літніх букетів і композицій.'),(158,'Квітка Шипшина','Розові','Декоративна','100-300 см','Рожевий, білий','Травень-Липень','09-01','11-30','Сонячне місце, помірний полив, дренований грунт','Помірні регіони','Родючий, слабокислий','10-25°C','Середня','https://upload.wikimedia.org/wikipedia/commons/5/5c/Rosa_canina2.jpg','Шипшина (Rosa canina) — це вид дикої троянди з родини Розових (Rosaceae), що росте в природі на теренах Європи, Азії та Північної Африки. Квітки шипшини мають ніжно-рожеве або біле забарвлення й часто зібрані в суцвіття. Рослина також відома своїми червоними ягодами, які використовуються в медицині та кулінарії завдяки своїм лікувальним властивостям.\nШипшина символізує любов, силу й вірність. Її плоди містять вітаміни й антиоксиданти, тому шипшину часто використовують для виготовлення чаїв, настоянок і варенів. Це також популярна рослина в декоративному садівництві, завдяки своїй здатності створювати природні живоплоти й клумби.'),(159,'Квітка Ятрофа','Молочайні','Сезонна','50-150 см','Червоний, рожевий','Літо','01-01','12-31','Сонячне місце, помірний полив, піщаний грунт','Теплі регіони','Піщаний, добре дренований','20-30°C','Середня','https://cdn.asterias.od.ua/images/200/200-4-26-700x798.jpg','Ятрофа (Jatropha) — це рід рослин з родини Молочайних (Euphorbiaceae), що налічує близько 200 видів. Ятрофа є часто декоративною рослиною з великими зеленими листками та яскравими квітами, які можуть бути червоними, жовтими або оранжевими, залежно від виду. В деяких видах ятрофи плоди містять токсичні олії, але інші використовуються в традиційній медицині для лікування різних захворювань.\nУ ландшафтному дизайні ятрофа часто використовується як екзотична рослина завдяки своїм енергійним кольорам і виразному вигляду. Її символізм пов''язаний з захистом і відновленням, а також з енергією та життєвим потенціалом.');

-- Налаштування лічильника SERIAL
SELECT setval(pg_get_serial_sequence('plants', 'id'), (SELECT MAX(id) FROM plants));